-- Legal jurisdictions (50 states, DC and federal)
--
-- Generated from the 2026-10-19 landlord-tenant research run (official sources only,
-- each link independently re-checked). Re-runnable: rows upsert on their stable id.

on conflict (id) do update set
  code = excluded.code,
  name = excluded.name,
  kind = excluded.kind,
  primary_law_citation = excluded.primary_law_citation,
  statewide_rent_cap = excluded.statewide_rent_cap,
  rent_control_preempted = excluded.rent_control_preempted,
  rent_regulation_summary = excluded.rent_regulation_summary,
  rent_regulation_source_url = excluded.rent_regulation_source_url,
  local_rent_control = excluded.local_rent_control,
  last_reviewed_at = excluded.last_reviewed_at,
  metadata = excluded.metadata,
  deleted_at = null;
