insert into property.legal_jurisdictions (id, code, name, kind, primary_law_citation, statewide_rent_cap, rent_control_preempted, rent_regulation_summary, rent_regulation_source_url, local_rent_control, last_reviewed_at, metadata) values
  ('e2d7f7f4-a8c7-54f8-9076-f9d925f8bc35', 'US', 'Federal', 'federal', 'Fair Housing Act, 42 U.S.C. 3601-3619', false, 'unknown', null, null, '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":[],"rentRegulationCorrections":[]}'::jsonb),
  ('76265595-5dfc-5906-aff3-d3c59796cb1c', 'AL', 'Alabama', 'state', 'Alabama Uniform Residential Landlord and Tenant Act, Ala. Code §§ 35-9A-101 to 35-9A-603 (Title 35, Chapter 9A)', false, 'yes', 'Alabama has no statewide rent cap. Ala. Code § 11-80-8.1 bars local governmental units from enacting, maintaining or enforcing ordinances, resolutions or rules that control rent charged for leasing private property; no 2024-2026 change to this section was identified.', null, '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":["Statute deep links: the official ALISON Code of Alabama renders in the browser and has no fetchable section deep links. Justia is used as the fallback; it returned HTTP 403 to automated fetch, so its URLs are confirmed by search only.","Statute: no separate rent-increase-notice or late-fee section was identified in Ch. 35-9A. The section URLs for § 35-9A-421 (pre-filing eviction notices) and § 35-9A-441 (periodic tenancy) were not confirmed.","Official guide: no landlord-tenant handbook from the Attorney General or a state agency was found. The listed handbook is published by nonprofits and legal aid.","Fair housing: no live state complaint page was found. The Alabama Fair Housing Law (Ala. Code 24-8) names ADECA, but ADECA''s own 2015/2020 fair-housing reports describe complaint intake as a recommendation. HUD and DOJ federal routes are listed instead.","Court self-help: judicial.alabama.gov and alacourt.gov refused connections in this session. A statewide judiciary self-help page was not opened; the county page and the form are listed unfetched.","Rental assistance: no currently live statewide renter assistance program was found. AHFA''s pandemic Emergency Rental Assistance has ended, and ahfa.com returned HTTP 403.","Code enforcement: no statewide housing-code enforcement page exists; enforcement is local."],"rentRegulationCorrections":[]}'::jsonb),
  ('6247b2b6-4986-5aae-928d-17b5c138c780', 'AK', 'Alaska', 'state', 'Alaska Uniform Residential Landlord and Tenant Act, AS 34.03.010-34.03.380 (eviction procedure: forcible entry and detainer, AS 09.45)', false, 'unknown', 'Alaska has no statewide rent cap. The Department of Law''s 2024 handbook says that without a lease, a landlord may raise rent on at least 30 days'' notice in a month-to-month tenancy.', 'https://law.alaska.gov/pdf/consumer/LandlordTenant_web.pdf', '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":["HUD state page: not sourced. hud.gov returned HTTP 403 and the session''s web-search budget ran out before the current Alaska URL could be confirmed by search.","Statute deep links: akleg.gov returned HTTP 403. Only the chapter URL (from the Department of Law page) is listed; section anchors for AS 34.03.070/.100/.180/.220/.290/.310 and the AS 09.45 FED procedure were not verified.","Court self-help (eviction): courts.alaska.gov refused connections. The handbook references the Court System''s FED eviction booklet and its Eviction Diversion (mediation) Program, but their URLs could not be confirmed.","Rental assistance: the AHFC website was unreachable and no currently live statewide renter assistance program was confirmed.","Rent regulation: whether any state statute preempts local rent control could not be confirmed, so it is set to unknown. No local rent-control ordinances were identified.","Health/code enforcement: no state agency page on mold, bed bugs or housing-code enforcement for renters was identified; the state health site returned 403."],"rentRegulationCorrections":[]}'::jsonb),
  ('c68b9035-0196-5503-a4ea-486e9847a03d', 'AZ', 'Arizona', 'state', 'Arizona Residential Landlord and Tenant Act, A.R.S. §§ 33-1301 to 33-1381 (Title 33, Chapter 10)', false, 'yes', 'Arizona has no statewide rent cap. A.R.S. § 33-1329 bars cities (including charter cities) and towns from controlling rents on private residential property, with exceptions for property owned, financed, insured or subsidized by a state agency, city or town.', 'https://www.azleg.gov/viewdocument/?docName=https://www.azleg.gov/ars/33/01329.htm', '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":["Court self-help: azcourts.gov returned HTTP 403, so the Arizona Judicial Branch''s own eviction self-help pages could not be opened or confirmed. The Arizona Bar Foundation portal is used instead.","Official guide: the Arizona Department of Housing Act page is listed unfetched (HTTP 403). The ADOH booklet PDF URL itself was not confirmed. No separate landlord-oriented state guide was found.","Statute: Arizona has no separate statutory rent-increase-notice section. Rent topics are covered by § 33-1329 (preemption), § 33-1381 (retaliatory increases) and § 33-1375 (periodic tenancy notice).","Rental assistance: no live statewide program run by the state housing agency was confirmed (housing.az.gov returned 403). Listed programs are local.","Health/code enforcement: azdhs.gov returned HTTP 403. No state housing-code enforcement agency exists; enforcement is municipal."],"rentRegulationCorrections":[]}'::jsonb),
  ('2f2698e1-8f83-5b3a-aa1a-1dbd2598bcc8', 'AR', 'Arkansas', 'state', 'Arkansas Residential Landlord-Tenant Act of 2007, Ark. Code Ann. § 18-17-101 et seq. (Title 18, Ch. 17); Landlord and Tenant, Ark. Code Ann. §§ 18-16-101 to 18-16-509 (incl. security deposits §§ 18-16-301 to 18-16-306)', false, 'yes', 'Arkansas has no statewide rent cap. Ark. Code Ann. § 14-16-601 (counties) and § 14-54-1409 (municipalities) preempt local rent control. Per search results, Act 459 of 2025 also bars local regulation of rental application fees and rental deposits; the enrolled act was not opened.', null, '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":["Statute deep links: the official Arkansas Code (LexisNexis public access) cannot be deep-linked and arkleg.state.ar.us was unreachable. The session''s web-search budget ran out before Justia URLs could be confirmed for the Residential Landlord-Tenant Act (Ch. 18-17), the landlord repair/habitability provisions, the unlawful detainer procedure (Ch. 18-60) and the failure-to-vacate statute (§ 18-16-101). Only the deposit and rent-control-preemption sections are listed.","Repairs/habitability: the AG page (undated) describes rentals as generally ''as is''. Whether statutory minimum habitability standards (reported as enacted in 2021) are in effect could not be verified against statute text in this session.","HUD state page: not sourced. hud.gov returned HTTP 403 and the search budget ran out before the Arkansas URL could be confirmed.","Court self-help: arcourts.gov was unreachable, so no Arkansas Judiciary self-help eviction page could be confirmed. The legal-aid form page is listed instead.","Rent regulation: Act 459 of 2025 (local preemption of rental application fee and deposit regulation) is reported by search results; the enrolled act on arkleg.state.ar.us could not be opened.","Code enforcement: no statewide housing-code enforcement page was found; enforcement is by cities."],"rentRegulationCorrections":[]}'::jsonb),
  ('0709455a-d6b0-5588-8d82-a0161e846c43', 'CA', 'California', 'state', 'California Civil Code, Hiring of Real Property, Cal. Civ. Code §§ 1940-1954.06; unlawful detainer procedure at Cal. Code Civ. Proc. §§ 1159-1179a', true, 'partial', 'The Tenant Protection Act (Civ. Code § 1947.12) caps annual rent increases for most covered units at 5% plus CPI or 10%, whichever is lower; SB 567 amended the Act effective April 1, 2024, and the section is set to sunset January 1, 2030. Many cities and counties have stricter local rent stabilization ordinances, but state law limits their scope: per the Attorney General, units with certificates of occupancy issued after February 1, 1995 and most single-family homes and condos are generally exempt from local caps (Los Angeles city also ended its RSO utility add-on starting February 2, 2026).', 'https://oag.ca.gov/rentcaps', array['Los Angeles (city RSO)','San Francisco','Oakland','Berkeley','Santa Monica','West Hollywood','San Jose','Los Angeles County (unincorporated)','Alameda','Hayward','Richmond','Antioch','Concord','San Leandro','Mountain View','East Palo Alto','Pasadena','Culver City','Beverly Hills','Inglewood','Pomona','Sacramento','Santa Ana','Palm Springs','Oxnard','Salinas','Baldwin Park','Bell Gardens','Commerce','Cudahy','Huntington Park','Maywood','Larkspur','Ojai','Thousand Oaks']::text[], '2026-10-19T00:00:00Z', '{"gaps":["HUD state page: hud.gov returns HTTP 403 to automated requests, so it is included unfetched, based on a search-confirmed URL.","Statute deep links: leginfo.legislature.ca.gov returns HTTP 403, so all statute links are unfetched, based on search results and links from AG pages. Costa-Hawkins (Civ. Code 1954.50-1954.535) was not linked because no URL could be confirmed.","Late fees: no separate late-fee statute section was identified or sourced.","Rental assistance: no live statewide emergency rental assistance program was verified. housing.ca.gov and hcd.ca.gov return HTTP 403, and the web-search quota ran out partway through the session.","Health/safety: the CDPH mold and lead pages could not be read (TLS certificate error or script-rendered content), so the federal EPA lead disclosure page is used instead. HCD State Housing Law pages return 403.","Local rent boards: the Oakland and San Jose program pages returned HTTP 403 and were left out. They are linked from oag.ca.gov/rentcaps.","2024-2026 changes noted from official sources: SB 567 (TPA amendments, effective 4/1/2024) and AB 12 (deposit cap, 7/1/2024). AB 628 (stove/refrigerator, 1/1/2026) and AB 414 (electronic deposit return) were found only in secondary sources and are not linked."],"rentRegulationCorrections":[{"correction":"The summary text is accurate: the 5%+CPI/10% cap, SB 567 effective 4/1/2024, the 1/1/2030 sunset (confirmed in the DRE 2026 guide), the post-2/1/1995 and single-family/condo exemptions from local caps, and the end of the LA RSO utility add-on on 2/2/2026. However, localJurisdictions is incomplete against the sourceUrl table, which also lists Baldwin Park, Bell Gardens, Commerce, Cudahy, Huntington Park, Maywood, Larkspur, Ojai and Thousand Oaks. The source also says Pomona''s RSO expires 12/31/2026 unless reauthorized and Salinas votes on repeal in Nov 2026. LAHD says the City of LA RSO maximum is 3% through 6/30/2027.","sourceUrl":"https://oag.ca.gov/rentcaps"}]}'::jsonb),
  ('d34f7d07-882c-5ca7-bf0f-01db44c6d1da', 'CO', 'Colorado', 'state', 'Colorado Revised Statutes Title 38, Article 12 (Tenants and Landlords: security deposits, warranty of habitability, for-cause eviction, etc.) and Title 13, Article 40 (Forcible Entry and Detainer)', false, 'yes', 'Colorado has no statewide rent cap, and state statute (C.R.S. 38-12-301) bars counties and municipalities from enacting rent control on private residential property; a 2023 bill to repeal that prohibition (HB23-1115) was lost, and a 2025 bill banning algorithmic rent-pricing coordination among landlords (HB25-1004) was vetoed on May 29, 2025. State law separately limits residential rent increases to once per 12-month period and requires 60 days'' notice of an increase where there is no written agreement (HB21-1121, 2021).', 'https://leg.colorado.gov/bills/hb23-1115', '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":["Statute deep links: the official C.R.S. is hosted only on LexisNexis (no stable deep links) and the Justia fallback returned HTTP 403. Section-level topics are covered by General Assembly bill pages instead of code sections.","HUD state page: hud.gov returns HTTP 403 to automated requests, and the web-search quota ran out before the Colorado URL could be confirmed (the California page is at hud.gov/states/california).","Official guide: no statewide AG or DOLA tenant/landlord handbook was found. The court eviction guide (JDF 100) and a short DOH page are the official guides included.","Retaliation: no separate source on the retaliation provision was linked.","Legal aid: the Colorado Legal Services site returned HTTP 403, so its housing section was not verified.","Mold/bed bugs: no CDPHE page on these was sourced. The lead page and the EPA disclosure rule are included."],"rentRegulationCorrections":[]}'::jsonb),
  ('fe799a57-c622-512b-8cf5-7fad3068cd65', 'CT', 'Connecticut', 'state', 'Conn. Gen. Stat. Chapter 830 (Rights and Responsibilities of Landlord and Tenant, §§ 47a-1 et seq.), Chapter 831 (Security Deposits, § 47a-21) and Chapter 832 (Summary Process, §§ 47a-23 et seq.)', false, 'unknown', 'Connecticut has no statewide rent cap or rent control; instead, municipal fair rent commissions under C.G.S. §§ 7-148b to 7-148f hear complaints about excessive rents. Public Act 22-30 required towns with 25,000 or more residents to establish a commission by July 1, 2023.', 'https://portal.ct.gov/doh/doh-1/housing/fair-rent-commissions', array['Branford','Bridgeport','Cheshire','Danbury','East Hartford','East Haven','Enfield','Fairfield','Farmington','Glastonbury','Hamden','Manchester','Mansfield','Meriden','Middletown','Milford','Naugatuck','New Britain','New Haven','New London','New Milford','Newtown','Norwalk','Norwich','Shelton','Southington','Trumbull','Waterbury','West Hartford','Westport','Wethersfield','Windsor','Clinton','Killingworth','Bristol','Groton','Torrington','Bloomfield']::text[], '2026-10-19T00:00:00Z', '{"gaps":["Statutes: cga.ct.gov refused all connections in this session. Chapter links are included unfetched because official court and agency pages link to them. Separate anchors for § 47a-13/47a-14h (tenant remedies, rent payment into court), § 47a-15a (late charges) and § 47a-20 (retaliation) could not be verified.","HUD state page: hud.gov returns HTTP 403, and the web-search quota ran out before the Connecticut URL could be confirmed.","Complaint filing: the AG complaint page does not mention landlord-tenant disputes. Only the Department of Banking deposit complaint process is landlord-specific.","Rental assistance: no open emergency rental assistance program was found. RAP''s waitlist is closed, and a DOH eviction-prevention URL from the sitemap returned 404.","Tenant''s summary process guide (JDP-HM-15): it moved to info.jud.ct.gov, which returned HTTP 403.","Rent regulation: no express state statute preempting local rent control was verified. No 2024-2026 statutory changes were confirmed (search quota exhausted)."],"rentRegulationCorrections":[{"correction":"The summary is accurate (§§ 7-148b to 7-148f; PA 22-30 requires towns of 25,000+ to adopt a commission ordinance by July 1, 2023). localJurisdictions omits towns the sourceUrl lists: Bristol, Groton and Torrington (mandatory) and Bloomfield (non-mandatory). The Judicial Branch booklet JDP-HM-31 (Rev. 1/26) also lists further towns required under PA 22-30, such as Greenwich, Ridgefield, South Windsor, Stratford, Vernon and Wallingford, and existing commissions such as Stamford and Simsbury.","sourceUrl":"https://portal.ct.gov/doh/doh-1/housing/fair-rent-commissions"}]}'::jsonb),
  ('d450a0d2-9479-53fd-93b0-72b8b970c6fb', 'DE', 'Delaware', 'state', 'Delaware Residential Landlord-Tenant Code, 25 Del. C. Part III, Chapters 51-59 (Chapter 57 Summary Possession); Manufactured Home Communities Act, 25 Del. C. Chapter 70', false, 'unknown', 'Delaware has no statewide rent cap or rent control for apartments; lot-rent increases in manufactured home communities are subject to rent increase justification rules in 25 Del. C. ch. 70, subch. VI. For other rentals, a landlord renewing a lease with modified terms, including rent, must give at least 60 days'' written notice (25 Del. C. § 5107).', 'https://delcode.delaware.gov/title25/c070/sc06/index.html', '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":["HUD state page: hud.gov returns HTTP 403, and the web-search quota ran out before the Delaware URL could be confirmed.","Official guide: the new Real Estate Commission ''Rights and Responsibilities Guide for Landlords and Tenants'' (24 Del. C. § 2925A; 25 Del. C. § 5124; 85 Del. Laws c. 277) could not be found online. The Real Estate Commission page did not link it.","Health/safety: the Division of Public Health lead pages blocked automated access (HTTP 999). The statute chapter and the EPA rule are included.","Rental assistance: no standalone, currently open emergency rental assistance program was verified. The DSHA page points to legal and crisis-line resources.","Rent regulation: whether state law preempts local rent control could not be verified, and no local rent control ordinances were found."],"rentRegulationCorrections":[]}'::jsonb),
  ('ac4a10a1-7962-5a54-b991-3539b8445319', 'DC', 'District of Columbia', 'state', 'Rental Housing Act of 1985, D.C. Code §§ 42-3501.01 et seq. (Title 42, Chapter 35 ''Rental Housing Generally''); housing regulations in Title 14 DCMR', true, 'no', 'D.C. runs a rent stabilization program under the Rental Housing Act of 1985 for non-exempt units, and all units must be registered with the Rental Accommodations Division. For increases taking effect May 1, 2026 through April 30, 2027, the Rental Housing Commission set the standard cap at 4.1% (CPI-W 2.1% + 2%) and 2.1% for registered elderly or disabled tenants (OTA notice dated Feb. 2, 2026).', 'https://ota.dc.gov/node/1816006', array['District of Columbia (rent stabilization administered by DHCD Rental Accommodations Division and the Rental Housing Commission)']::text[], '2026-10-19T00:00:00Z', '{"gaps":["hud_state_page: HUD''s D.C. page could not be fetched (connection refused, then 403); the URL is from search results only.","court_self_help: dccourts.gov blocks automated fetching (403); both court pages are included with fetched=false.","rental_assistance: erap.dhs.dc.gov returned 403, and current ERAP intake status (paused or open) could not be confirmed.","statute (repairs): no single D.C. Code section on the landlord repair duty or tenant repair remedies was sourced. Housing-code standards are in DCMR regulations (Title 14 and the property maintenance code), which were not opened; repair resources here are DOB, the Housing Conditions Court and § 42-3505.02.","statute (security deposits): the companion regulations 14 DCMR §§ 308-311 were not opened.","official_guide: the OTA Tenant Resource Guide PDF (Apr. 2024) returned 404. No separate official landlord-oriented D.C. guide was found beyond the DHCD rent control and registration pages."],"rentRegulationCorrections":[]}'::jsonb),
  ('70920cc2-fa45-5be2-abd5-09b8371ac0c6', 'FL', 'Florida', 'state', 'Florida Residential Landlord and Tenant Act, Fla. Stat. ch. 83, Part II (§§ 83.40-83.684)', false, 'yes', 'Florida has no statewide rent cap. Fla. Stat. §§ 125.0103 and 166.043 bar counties and municipalities from adopting measures that control rents, except land-use tools that increase affordable housing, and § 83.425 (2023) preempts local regulation of residential tenancies.', 'http://www.leg.state.fl.us/statutes/index.cfm?App_mode=Display_Statute&URL=0100-0199/0125/Sections/0125.0103.html', '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":["hud_state_page: no current HUD Florida tenant-rights URL was found. Search returned only an archived 2020 ''Rental Help: Florida'' copy, and hud.gov blocks automated fetching.","court_self_help: no flcourts.gov self-help page for landlord-tenant cases was located (the homepage content was truncated). The Florida Bar''s Supreme Court-approved forms page is included with fetched=false (403).","complaint_filing: the Attorney General site (myfloridalegal.com) returned 403. FDACS''s complaint portal is used, but the portal page does not itself list landlord-tenant as a subject.","rental_assistance: no live statewide emergency rental assistance program was found; Florida Housing directs renters to local SHIP offices.","statute (rent increase / late fees): no Florida statute specifically governing rent-increase notice or late-fee amounts was found in Part II. Notice to end periodic tenancies is in § 83.57, and local rules are preempted by § 83.425.","official_guide: no official revision date is shown on the FDACS page, and no current official FDACS brochure PDF was found.","health_safety: no Florida state lead-disclosure page was opened; federal rules (EPA/HUD) would apply."],"rentRegulationCorrections":[{"correction":"Precision only, not an error. Saying both sections were amended in 2023 (ch. 2023-17) is true but incomplete: both were last amended by ch. 2024-27 (125.0103: s. 1; 166.043: s. 2), according to the 2026 History lines. The 2024 change touched the towing/immobilization-rate paragraphs; the rent-control bar in subsection (2) and the affordable-housing exception in (3) read as summarized. Section 83.425 history (s. 1, ch. 2023-314) confirmed.","sourceUrl":"http://www.leg.state.fl.us/statutes/index.cfm?App_mode=Display_Statute&URL=0100-0199/0125/Sections/0125.0103.html"}]}'::jsonb),
  ('3d108e60-db41-5076-ac35-06cae2cf2bca', 'GA', 'Georgia', 'state', 'O.C.G.A. Title 44, Chapter 7 (Landlord and Tenant), §§ 44-7-1 et seq.', false, 'yes', 'Georgia has no statewide rent cap. O.C.G.A. § 44-7-19 bars counties and municipalities from regulating the amount of rent on privately owned residential rental property. The 2024 Safe at Home Act (HB 404, effective July 1, 2024) addressed habitability, deposits and pre-filing notice, not rent levels.', null, '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":["statute: no official deep links were obtained for O.C.G.A. Title 44, Ch. 7 (§§ 44-7-13/-14 repair, 44-7-19 rent-control preemption, 44-7-24 retaliation, 44-7-30 to -37 deposits, 44-7-50 et seq. dispossessory). The official code is hosted by LexisNexis behind a JavaScript viewer, and Justia (the fallback) returned 403; only a superseded 2022 Justia URL for § 44-7-34 was confirmed by search.","rent_regulation: no official fetchable source for § 44-7-19 was found, so rentRegulation.sourceUrl points to Justia''s 2024 Georgia Code index (confirmed by search, not fetched).","statute (2024 changes): the HB 404 (Safe at Home Act, 2024) bill page on legis.ga.gov was not reached. Its provisions (habitability, deposit cap of two months'' rent, 3-day pre-filing notice) are confirmed only by secondary sources and by the DCA handbook (rev. 8-29-24).","hud_state_page: hud.gov returns 403. Only HUD''s Georgia ''renting'' page URL is confirmed, not a ''Tenant Rights, Laws and Protections'' page.","complaint_filing: the AG Consumer Protection Division states no state agency can intervene in landlord-tenant disputes, so there is no confirmed state landlord-tenant complaint channel.","rental_assistance: the Georgia Rental Assistance (GRA) site (georgiarentalassistance.ga.gov) loaded but its open or closed status could not be determined, so it was not listed.","court_self_help: no Judicial Council (georgiacourts.gov) self-help page for dispossessory cases was located; the magistrate council forms page is used instead.","Direct link to O.C.G.A. Chapter 44-7 or a single section of it: the state''s only free official copy of the Code (LexisNexis public access, linked from legis.ga.gov) works through sessions in a JavaScript app and has no stable links to chapters or sections. No other official government site publishes the codified text.","Session-law text of recent Chapter 44-7 amendments (for example the 2024 Safe at Home Act, HB 404) on legis.ga.gov: not sourced. Bill documents load through a legislature API that needs a token, and this session''s web-search budget was used up, so the document link could not be found and checked."],"rentRegulationCorrections":[{"correction":"No factual error found in the summary, but the source is weak. sourceUrl is the generic index of an unofficial (Justia) 2024 Georgia Code, not O.C.G.A. § 44-7-19 itself, and it returned a Cloudflare 403. The § 44-7-19 wording could not be checked against it. Point sourceUrl at the specific § 44-7-19 page (latest edition), or at the official LexisNexis public-access OCGA linked from legis.ga.gov. I separately confirmed the HB 404 / July 1, 2024 framing: the DCA handbook revised 8-29-24 reflects the 3-business-day pre-filing notice. The claim of no 2024-2026 preemption change could not be re-verified because web search was unavailable.","sourceUrl":"https://law.justia.com/codes/georgia/2024/"}]}'::jsonb),
  ('46d51c73-d084-5ed6-8fe2-215cb1bf77f5', 'HI', 'Hawaii', 'state', 'Residential Landlord-Tenant Code, Haw. Rev. Stat. ch. 521 (§§ 521-1 to 521-85)', false, 'unknown', 'Hawaii has no statewide rent control law; HRS § 521-21 sets notice periods for rent increases and caps late charges. Since Aug. 9, 2023, the governor''s wildfire emergency proclamations have held residential rents on Maui at Aug. 9, 2023 levels; the 33rd proclamation (Oct. 16, 2026) runs through Dec. 15, 2026 unless superseded.', 'https://dod.hawaii.gov/hiema/active-state-emergency-proclamations/', array['Island of Maui (emergency prohibition on residential rent increases under HRS § 127A-30 wildfire proclamations)']::text[], '2026-10-19T00:00:00Z', '{"gaps":["hud_state_page: no current HUD Hawaii tenant-rights URL could be located by search, and hud.gov blocks automated fetching.","official_guide / fair_housing: cca.hawaii.gov (Office of Consumer Protection) and labor.hawaii.gov (Hawaii Civil Rights Commission) return 403, so those resources are included only as fetched=false. The HCRC main complaint page URL was not confirmed.","complaint_filing: no Attorney General or consumer-protection complaint page for landlord-tenant issues was confirmed. OCP runs a Landlord-Tenant Information Center (per search results), but its page could not be opened.","rental_assistance: no currently live statewide renter or emergency rental assistance program page was sourced.","health_safety / code_enforcement: no Hawaii Department of Health page on lead, mold or housing-code enforcement for rentals was sourced.","rent_regulation: whether state law preempts county rent control could not be determined from an official source, so it is marked unknown.","statute: HRS § 521-63 (tenant remedies for landlord failures) and § 521-78 (rent trust fund) could not be opened because of intermittent HTTP 522 errors on data.capitol.hawaii.gov."],"rentRegulationCorrections":[{"correction":"The summary says the 32nd proclamation runs through Oct. 23, 2026. It has been superseded: the Thirty-Third Proclamation Relating to Wildfires (Oct. 16, 2026) supersedes all earlier ones and runs through Dec. 15, 2026 unless terminated or superseded. It continues the Maui-only HRS §127A-30(a)(1) rent freeze at Aug. 9, 2023 levels. Documented added operating expenses may be passed on, increases in written instruments signed before Aug. 9, 2023 may proceed, and qualifying 201H/Maui County Code ch. 2.96-2.97 regulated affordable projects are excluded. Update sourceUrl to the 33rd proclamation, or better to https://dod.hawaii.gov/hiema/active-state-emergency-proclamations/, since new proclamations come about every 60 days.","sourceUrl":"https://dod.hawaii.gov/hiema/files/2026/10/2610025_THIRTY-THIRD-PROCLAMATION-RELATING-TO-WILDFIRES.pdf"}]}'::jsonb),
  ('0d9d282a-e917-5d0b-8142-9b37b126cc5c', 'ID', 'Idaho', 'state', 'Idaho Code Title 6, Chapter 3 (Forcible Entry and Unlawful Detainer, incl. landlord-tenant sections 6-316 to 6-324) and Title 55, Chapter 3 (Rights and Obligations of Owners, incl. 55-304 to 55-306)', false, 'yes', 'Idaho has no statewide rent cap. Idaho Code 55-306 (''Local Government - No Rent Control''), added in 2025 (ch. 65), bars local governments from regulating rent, fees or deposits on private residential rentals; this prohibition was commonly cited as 55-307 before the 2025 reorganization of Title 55, Chapter 3.', 'https://legislature.idaho.gov/statutesrules/idstat/Title55/T55CH3/SECT55-306/', '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":["Web search quota for the session ran out partway through, so several items could only be found by browsing outward from official pages.","Statute pages: legislature.idaho.gov refused all automated connections. The chapter and section URLs were confirmed through web search results only (fetched=false). Separate eviction-procedure section links (6-303, 6-310, 6-316) and a retaliation section were not confirmed.","court_self_help: courtselfhelp.idaho.gov and isc.idaho.gov returned HTTP 403. The eviction/landlord-tenant page on the self-help site was not located.","legal_aid_directory: idaholegalaid.org returned HTTP 403, so its housing section could not be confirmed.","hud_state_page: hud.gov returns 403 to automated fetching, and the Idaho ''Tenant Rights'' subpage URL was not verified. Only the state landing page is listed, using a link found on an Idaho Housing page.","complaint_filing: the AG consumer complaint form (ag.idaho.gov online forms) does not mention landlord-tenant disputes, and the AG manual states the office does not enforce landlord-tenant law, so no landlord-tenant complaint channel is listed.","rental_assistance: no currently open statewide emergency rental assistance program was found. Only Housing Choice Voucher information is listed.","code_enforcement: no state-level housing code enforcement page was found. Idaho relies on local codes."],"rentRegulationCorrections":[]}'::jsonb),
  ('ea69185e-946c-5993-8638-a9f20389da9b', 'IL', 'Illinois', 'state', 'No single residential landlord-tenant act; key statutes: Landlord and Tenant Act (765 ILCS 705), Security Deposit Return Act (765 ILCS 710), Security Deposit Interest Act (765 ILCS 715), Landlord Retaliation Act (765 ILCS 721), Residential Tenants'' Right to Repair Act (765 ILCS 742), Eviction Act (735 ILCS 5/Art. IX)', false, 'yes', 'Illinois has no statewide rent cap. The Rent Control Preemption Act (50 ILCS 825) bars local governments from enacting rent control, and the Attorney General''s January 2024 fact sheet confirms Illinois has no rent control law. A separate rental fee-disclosure law, including a $50 application-fee cap, takes effect January 1, 2027.', 'https://illinoisattorneygeneral.gov/Page-Attachments/LandlordAndTenantRightsLaws.pdf', '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":["Web search quota for the session ran out partway through, so statute URLs were taken from links on fetched Illinois Legal Aid Online pages instead of from search.","Statutes: ilga.gov refused all automated connections (ECONNREFUSED), so every ILCS link is fetched=false. The Rent Control Preemption Act (50 ILCS 825) page URL could not be found or opened, so the rent-control status relies on the Attorney General fact sheet plus general knowledge of the Act. The ILCS citation for the Residential Tenants'' Right to Repair Act (765 ILCS 742) is from general knowledge.","hud_state_page: hud.gov returns 403 to automated fetching, and no Illinois HUD tenant-rights page URL could be confirmed.","complaint_filing: the Attorney General''s File-A-Complaint page has no landlord-tenant category, and its rental page says the office lacks authority in most rental matters. Its Civil Rights Bureau takes pattern-and-practice housing discrimination complaints. No landlord-tenant complaint channel is listed.","Rental assistance: IDHS''s illinoisrentalassistance.org could not be opened (TLS error), so only CBRAP is listed.","Local ordinances: chicago.gov, codelibrary.amlegal.com and library.municode.com returned 403. Evanston, Oak Park, Mount Prospect, Urbana and DeKalb ordinances are listed on ILAO''s landlord-tenant-laws page but were not added separately.","code_enforcement: no statewide housing-code enforcement agency page was found. Enforcement is municipal."],"rentRegulationCorrections":[]}'::jsonb),
  ('1bc81a15-f3f4-5b5a-890c-61647e94f37f', 'IN', 'Indiana', 'state', 'Indiana Code Title 32, Article 31 - Landlord-Tenant Relations (IC 32-31)', false, 'yes', 'Indiana has no statewide rent cap. IC 32-31-1-20 prohibits local units of government from regulating rent on privately owned residential property.', 'https://iga.in.gov/laws/2025/ic/titles/32#32-31', '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":["Every in.gov host (courts, Attorney General, Civil Rights Commission, IHCDA, health department) refused automated connections (ECONNREFUSED), and the shared web search quota ran out. In.gov URLs listed are fetched=false and were confirmed only by links on fetched pages or by one search.","Statutes: the IGA code site (iga.in.gov) is a JavaScript app that does not render for automated fetch, and Justia returned 403. Chapter fragment links and citations (IC 32-31-1-20, 32-31-3, 32-31-8) are from general knowledge and need verification. No separate eviction-procedure, retaliation or late-fee section was confirmed.","fair_housing: the Indiana Civil Rights Commission housing complaint page could not be reached or its URL verified. Only a private nonprofit fair housing center is listed.","official_guide: no current state-published tenant/landlord handbook was found. The court''s Small Claims Manual has a landlord-tenant section.","hud_state_page: hud.gov returns 403 and no Indiana HUD page URL was confirmed.","rental_assistance: no IHCDA or other currently open statewide rental assistance page could be verified.","health_safety / code_enforcement: no state health department lead or housing-code page could be verified because in.gov was unreachable.","Indiana tenant/landlord guide published only by a state agency (AG, IHCDA or courts on in.gov): could not be checked. Every in.gov host (www.in.gov, secure.in.gov) refused connections or timed out from this environment, and the session''s web-search budget ran out, so no in.gov-hosted guide could be opened."],"rentRegulationCorrections":[]}'::jsonb),
  ('1231c435-e754-5c6d-9ee7-8d63d33916ee', 'IA', 'Iowa', 'state', 'Iowa Uniform Residential Landlord and Tenant Act, Iowa Code chapter 562A (Iowa Code 2026); evictions under Iowa Code chapter 648 (forcible entry and detainer)', false, 'yes', 'Iowa has no statewide rent cap. Iowa Code 364.3(9) bars cities from limiting the rent charged for private residential or commercial property, and 364.3(16) has voided local source-of-income (housing voucher) ordinances since January 1, 2023.', 'https://www.legis.iowa.gov/docs/code/364.3.pdf', '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":["Web search quota for the session ran out, so resources were found by browsing outward from official sites.","official_guide: no state-published tenant/landlord handbook was found. The Attorney General refers landlord-tenant matters elsewhere. Legal aid and nonprofit guides are listed instead.","complaint_filing: the AG''s consumer complaint process does not cover ordinary landlord-tenant disputes, so no landlord-tenant complaint channel is listed.","court_self_help: iowacourts.gov has no eviction-specific self-help page or form set. Only the small claims page is listed.","hud_state_page: hud.gov returns 403 to automated fetching, and the Iowa ''Tenant Rights'' subpage was not verified.","rental_assistance: no currently open statewide emergency rental assistance program was found. Iowa Finance Authority (opportunityiowa.gov) lists housing search tools and an HCBS rent subsidy only.","code_enforcement: no statewide housing-code enforcement page was found. Rental inspection is municipal.","Iowa landlord-tenant handbook from a state agency: none found. The Iowa AG''s Home & Property page links only to HOME, Inc. and Iowa Legal Aid. The Iowa Judicial Branch ''Videos and Brochures'' and small-claims pages have no landlord-tenant brochure. The Iowa Civil Rights Commission resources and Iowa Finance Authority rental pages have no tenant handbook. The web-search budget ran out, so nothing more could be searched."],"rentRegulationCorrections":[]}'::jsonb),
  ('94612f08-ab20-59ca-9c46-5e10f100d8f5', 'KS', 'Kansas', 'state', 'Kansas Residential Landlord and Tenant Act, K.S.A. 58-2540 to 58-2573; eviction procedure, K.S.A. 61-3801 to 61-3808 (Chapter 61, Article 38)', false, 'yes', 'Kansas has no statewide rent cap. K.S.A. 12-16,120 bars cities, counties and other political subdivisions from controlling rent on private residential or commercial property, with exceptions for property they own and voluntary incentive agreements.', 'https://kslegislature.gov/laws/012_000_0000_chapter/012_016_0000_article/012_016_0120_section/012_016_0120_k/', '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":["official_guide: No current state-agency tenant or landlord handbook was found. ag.ks.gov returned 403. Kansas Legal Services hosts a 2007 landlord handbook from HCCI, a nonprofit; it is outdated and was left out.","hud_state_page: hud.gov returned 403 to fetching, and a search found no current per-state HUD ''Tenant Rights, Laws and Protections'' page for Kansas. The page may have been removed in the 2025 redesign; this is unconfirmed.","court_self_help: The kscourts.gov and kjc.ks.gov pages are included as fetched=false because both sites return 403.","fair_housing: The Kansas Human Rights Commission site (khrc.net) fails HTTPS with a certificate mismatch. Its complaint page is linked from Kansas Legal Services and is included as fetched=false.","code_enforcement / health_safety: Kansas has no statewide housing code. HB 2634, which would create a default maintenance code, is shown as introduced only. KDHE pages return 403, so the EPA federal lead page is used.","Kansas statutes have no repair-and-deduct, rent-escrow, late-fee or general rent-increase-notice sections; the rent_increase tag rests on the retaliation statute, K.S.A. 58-2572.","The shared web-search budget ran out mid-task, so some official pages could not be searched for.","Kansas Attorney General landlord-tenant handbook: none could be verified. ag.ks.gov returned HTTP 403 to automated fetches, and earlier search results found no AG-published Kansas landlord-tenant handbook."],"rentRegulationCorrections":[]}'::jsonb),
  ('5d50dc3e-8cbd-5334-928f-f8df375215c9', 'KY', 'Kentucky', 'state', 'KRS Chapter 383 (Landlord and Tenant), including Forcible Entry and Detainer, KRS 383.200-383.290, and the Uniform Residential Landlord and Tenant Act, KRS 383.500-383.715 (applies only in cities and counties that adopted it)', false, 'partial', 'Kentucky has no statewide rent cap and no local rent control. KRS 383.198 (effective March 6, 2024) bars local governments from adopting or enforcing landlord-tenant ordinances that conflict with state law, and under KRS 383.500 a local government may adopt the Uniform Residential Landlord and Tenant Act only in full, without amendment, and may not enact other ordinances on its subjects.', 'https://apps.legislature.ky.gov/law/statutes/statute.aspx?id=54458', '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":["official_guide: No state-published tenant or landlord handbook was found. ag.ky.gov returned 403, and neither Kentucky Housing Corporation nor legal-aid sites link one.","court_self_help: kycourts.gov returns 403 to automated fetching. Only the AOC-216 form link (via Kentucky Justice Online) is included, and no judiciary landlord-tenant self-help page was confirmed.","hud_state_page: hud.gov returned 403, and a search found no current per-state HUD tenant-rights page for Kentucky.","fair_housing / complaint_filing: The Kentucky Commission on Human Rights and Attorney General pages are search-confirmed only (fetched=false) because of 403 responses.","health_safety: Kentucky state health (CHFS) pages were not reachable or checked, so the EPA federal lead page is used.","The repair, deposit, access and retaliation statutes are URLTA sections that apply only in adopting localities. Elsewhere, KRS 383 has no statewide habitability, deposit, late-fee or rent-increase-notice statute.","The shared web-search budget ran out mid-task, which limited discovery of ky.gov pages.","Statewide government-published general tenant/landlord handbook for Kentucky: none found. Kentucky''s URLTA (KRS 383.505-383.715) applies only in localities that adopted it. ag.ky.gov, kycourts.gov, legislature.ky.gov/LRC and louisvilleky.gov all returned HTTP 403 to automated fetches, so any AG or court brochure could not be verified. Web search budget was exhausted this pass."],"rentRegulationCorrections":[{"correction":"KRS 383.500''s text is not limited to URLTA-adopting localities. Its last sentence reads ''No other ordinance shall be enacted by a city, county or urban-county government which relates to the subjects embraced in KRS 383.505 to 383.705.'' Rephrase it as barring cities, counties and urban-county governments from enacting other ordinances on URLTA subjects, and requiring any adoption to be in full and without amendment. The KRS 383.198 details (2024 Ky. Acts ch. 3, effective March 6, 2024) are accurate.","sourceUrl":"https://apps.legislature.ky.gov/law/statutes/statute.aspx?id=35717"}]}'::jsonb),
  ('6d2a5fb4-c901-5c20-85c4-35eb49f0d53b', 'LA', 'Louisiana', 'state', 'La. Civil Code arts. 2668-2729 (Lease); La. R.S. 9:3251-3254 (residential security deposits); La. Code Civ. Proc. arts. 4701 et seq. (Eviction of Tenants and Occupants)', false, 'yes', 'Louisiana has no statewide rent cap, and no Louisiana locality has rent control. La. R.S. 9:3258 is the statute generally cited as barring local governments from adopting rent control.', null, '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":["statute: legis.la.gov refused all connections from the fetch tool, so every Louisiana statute link is search-confirmed (fetched=false). No search-confirmed deep links were found for C.C. art. 2668 (start of the Lease title), C.C. art. 2691, R.S. 9:3251 (deposit return deadline), C.C.P. art. 4731 (eviction rule) or R.S. 9:3258 (rent control).","rentRegulation.sourceUrl is empty: no official URL for La. R.S. 9:3258 could be found or opened. The preemption is reported by secondary sources only.","official_guide: The Attorney General site (ag.louisiana.gov) refused connections, and no state-published tenant or landlord handbook was verified.","court_self_help: No statewide judiciary landlord-tenant self-help page was found; lasc.org returned an empty page. Evictions are heard in parish and city courts.","legal_aid: louisianalawhelp.org returned 403, so the Louisiana Civil Legal Navigator is used instead.","complaint_filing: No Attorney General consumer-complaint URL could be confirmed; the search budget was exhausted.","hud_state_page: hud.gov returned 403, and no current per-state HUD tenant-rights page was found.","health_safety / code_enforcement: The Louisiana Department of Health was not reachable or checked, so the EPA federal lead page is used.","2026 change: HB 292 (2026 RS, eff. Aug. 1, 2026) changed security-deposit accounting timing. Sources disagree on the Act number (62 vs 63) and it could not be checked on legis.la.gov. HB 297 (reported as Act 64) extended early lease termination to stalking survivors.","The shared web-search budget ran out repeatedly during this jurisdiction.","Judiciary-published statewide landlord-tenant self-help page: none found. lasc.org and the Law Library of Louisiana research guides (lasc.libguides.com, checked via sitemap) have no landlord-tenant or eviction guide. Statewide eviction self-help comes through the Access to Justice Commission forms above, and parish courts vary.","Louisiana AG landlord-tenant guide on the AG''s own site: could not be opened. ag.louisiana.gov refused connections and the LDH-hosted copy returned 403. It is listed above as fetched=false and needs a manual check."],"rentRegulationCorrections":[{"correction":"sourceUrl is empty, so the summary cites no primary source. It relies on ''secondary sources'' for La. R.S. 9:3258. legis.la.gov was unreachable from the audit environment, so 9:3258 could not be opened and no factual error was confirmed. Add the official legis.la.gov URL for R.S. 9:3258 once it is verified manually.","sourceUrl":""}]}'::jsonb),
  ('9249eb28-5387-5a29-a419-0569317f287a', 'ME', 'Maine', 'state', 'Me. Rev. Stat. tit. 14, ch. 709 (Entry and Detainer, §§6000-6017), ch. 710 (Rental Property, §§6021-6030-K), ch. 710-A (Security Deposits, §§6031-6039)', false, 'no', 'Maine has no statewide rent cap and no statute preempting local rent control. Portland has a voter-approved (2020) rent control ordinance administered with a Rent Board. Statewide, 14 M.R.S. §6015 requires 45 days'' notice of rent increases and 75 days for increases of 10% or more (PL 2023, c. 388), and §6016 bars increases on units that violate the warranty of habitability.', 'https://www.portlandmaine.gov/rent-control-rental-housing-rights', array['Portland']::text[], '2026-10-19T00:00:00Z', '{"gaps":["hud_state_page: hud.gov returned 403, and a search found no current per-state HUD tenant-rights page for Maine.","fair_housing: Maine Human Rights Commission pages are search-confirmed only (fetched=false); www.maine.gov returns 403 and the mirrors redirect MHRC pages.","Maine AG pages were fetched on the www1.maine.gov mirror; the canonical www.maine.gov host returns 403 to automated fetching.","rent_regulation: Portland''s pages load content dynamically, so the ordinance text and the current allowable increase were not confirmed on the city site. News reports put the cap at 2.2% for 2026 and 2.6% for 2027. Other Maine municipalities were not checked for rent ordinances.","Recent changes: PL 2023, c. 388 (75-day notice for 10%+ increases) and PL 2023, c. 594 (fees, move-in payment limit, total price disclosure). 2025 amendments: PL 2025, c. 515 (§6021), c. 139 (§6001), c. 767 (§6025), plus a 2025 law requiring an AG model lease. A 2025 statewide rent-stabilization bill (LD 1534) is reported as not enacted; unconfirmed on an official page.","health_safety: The Maine CDC lead program page (linked from the AG page) was not opened.","The shared web-search budget ran out during the task."],"rentRegulationCorrections":[]}'::jsonb),
  ('5bdc5fbc-491d-5408-af9b-4cd9875da494', 'MD', 'Maryland', 'state', 'Md. Code Ann., Real Property, Title 8 (Landlord and Tenant), §§ 8-101 et seq. (Maryland General Assembly, mgaleg.maryland.gov)', false, 'no', 'Maryland has no statewide rent cap; DHCD''s Tenants'' Bill of Rights (effective Oct. 1, 2026) states that some local jurisdictions may limit increases but no statewide law limits rent increases at renewal, and Real Property § 8-209 requires 90 days'' written notice for most increases. Montgomery County''s rent stabilization law took effect July 23, 2024 (5.2% cap for 2026-27) and Takoma Park''s allowance is 3% for 2026-27.', 'https://dhcd.maryland.gov/media/490', array['Montgomery County (Rent Stabilization law enacted July 20, 2023, effective July 23, 2024; County Code ch. 29, §§ 29-56 to 29-62; 5.2% maximum for July 1, 2026 - June 30, 2027)','City of Takoma Park (rent stabilization; 3% allowance for July 1, 2026 - June 30, 2027; policy review under way with recommendations expected early 2027)']::text[], '2026-10-19T00:00:00Z', '{"gaps":["hud_state_page: hud.gov returned HTTP 403 to every automated fetch and web search was unavailable, so the current HUD Maryland tenant-rights URL could not be confirmed.","complaint_filing (statewide): Attorney General Consumer Protection Division pages (old marylandattorneygeneral.gov URLs now redirect to oag.maryland.gov) returned 403; no complaint URL confirmed. Only the Montgomery County local complaint page is included.","health_safety: Maryland Department of the Environment Lead Poisoning Prevention Program (mde.maryland.gov) returned 403; no lead/rental-registration page confirmed.","rent_regulation: Prince George''s County website returned 403, so any county rent stabilization status there was not verified.","statute: mgaleg.maryland.gov has no chapter-level Title 8 page; sections are deep-linked individually. No separate repair-and-deduct statute; § 8-211 rent escrow is the repair remedy.","rental_assistance: no dedicated statewide emergency rental assistance program found live; the DHCD resources page lists other programs."],"rentRegulationCorrections":[]}'::jsonb),
  ('e03ff58b-32ad-54f6-adbe-b6c4776c56a0', 'MA', 'Massachusetts', 'state', 'Mass. Gen. Laws ch. 186 (Estates for Years and at Will; incl. § 15B security deposits) and ch. 239 (Summary Process); State Sanitary Code, 105 CMR 410', false, 'yes', 'Massachusetts has no statewide rent cap, and local rent control has been prohibited since the 1994 ballot vote (M.G.L. c. 40P). A 2026 initiative to cap annual increases at CPI or 5% was kept off the November 2026 ballot by the Supreme Judicial Court in June 2026, and the Legislature did not enact it.', 'https://malegislature.gov/Laws/GeneralLaws/PartI/TitleVII/Chapter40P', '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":["statute: malegislature.gov refused every connection; deep links for c. 186 § 15B (deposits), § 14 (quiet enjoyment/utilities), § 18 (retaliation), c. 239 (summary process), c. 239 § 8A (rent withholding), c. 111 § 127L (repair and deduct) and c. 40P (rent control prohibition) could not be opened or confirmed.","Mass.gov (Attorney General, Housing Court self-help, EOHLC, DPH, MCAD) returned 403 to all automated fetches; mass.gov URLs are included only when confirmed via a link on an opened page or via web search, all with fetched=false.","hud_state_page: hud.gov returned 403 and web search was unavailable; not sourced.","complaint_filing: Attorney General consumer complaint page not confirmed (mass.gov blocked, search budget exhausted).","health_safety: State Sanitary Code (105 CMR 410) and DPH Childhood Lead Poisoning Prevention / lead law pages on mass.gov could not be opened or confirmed; only local code-enforcement pages are included.","court_self_help: no statewide Housing Court eviction self-help or forms page confirmed; only the Eastern Housing Court location page and MassLegalHelp forms are included.","rent_regulation: 2026 ballot status comes from Ballotpedia and news search results; the Secretary of the Commonwealth page rendered empty and could not confirm the question number or final certification."],"rentRegulationCorrections":[{"correction":"Outdated and wrong. The summary says the CPI-or-5% initiative is ''reported as headed for the November 3, 2026 ballot''. It is not on that ballot. The Elections Division certified 88,132 signatures on Dec 18, 2025, and the measure went to the Legislature. On June 23-24, 2026 the Supreme Judicial Court ruled it could not appear on the November 2026 ballot because its exemption for religious facilities improperly made religion a factor in the petition. The Legislature did not pass the proposed compromise; Homes for All Massachusetts says ''The legislature had its chance to act this session and didn''t''. The campaign plans to pursue legislation and a 2028 ballot run. The 1994 ban (c. 40P) therefore stays in force, and there is no statewide cap or local rent control. The sourceUrl is Ballotpedia, not an official source; replace it with the c. 40P text or the SJC decision once those can be opened.","sourceUrl":"https://www.ballotpedia.org/Massachusetts_Rent_Control_Initiative_(2026)"}]}'::jsonb),
  ('55070f73-899e-57ed-b168-b4a7c003e4bf', 'MI', 'Michigan', 'state', 'Mich. Comp. Laws ch. 554 (incl. MCL 554.139 lessor covenants; Security Deposits Act, MCL 554.601-554.616; Truth in Renting Act, MCL 554.631-554.641) and Revised Judicature Act summary proceedings, MCL 600.5701-600.5759 (citations not verified against the official site in this session)', false, 'yes', 'Michigan has no statewide rent cap. 1988 PA 226 (MCL 123.411) prohibits local governments from enacting rent control on private residential property.', 'https://www.legislature.mi.gov/', '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":["statute: legislature.mi.gov returned 403 to every fetch and web search was unavailable, so no section deep links (MCL 554.139, 554.601-.616, 554.631-.641, 600.5714, 600.5720, 123.411) could be verified; only the site root is included, with citations in the notes.","official_guide (state): michigan.gov (Attorney General, MSHDA, MDCR, MDHHS) and courts.michigan.gov returned 403 to all fetches; no state agency tenant/landlord guide confirmed. The MJI benchbook is link-confirmed only (fetched=false).","court_self_help: courts.michigan.gov returned 403; Michigan Legal Help self-help centers page used instead.","fair_housing: Michigan Department of Civil Rights (michigan.gov/mdcr) returned 403; nonprofit fair housing center and Michigan Legal Help used instead.","complaint_filing: Attorney General consumer complaint page not confirmed (michigan.gov blocked; search returned only an Aug. 13, 2026 AG press release).","rental_assistance: MSHDA site blocked and no currently live statewide emergency rental assistance program verified.","health_safety: MDHHS lead/healthy-homes pages blocked; no state health-safety page confirmed.","hud_state_page: hud.gov returned 403 and web search was unavailable; not sourced.","rent_regulation: preemption statute (MCL 123.411) not opened; status stated from the known statute without an official deep link."],"rentRegulationCorrections":[]}'::jsonb),
  ('b098a883-752c-59b6-b865-998df5de56a8', 'MN', 'Minnesota', 'state', 'Minn. Stat. ch. 504B (Landlord and Tenant)', false, 'partial', 'Minnesota has no statewide rent cap. Minn. Stat. § 471.9996 bars local rent control unless voters approve it at a general election. Saint Paul''s voter-approved ordinance limits increases to 3% per 12 months, with exceptions; it was amended effective Jan. 1, 2023 and June 13, 2025.', 'https://www.revisor.mn.gov/statutes/cite/471.9996', array['Saint Paul (Rent Stabilization Ordinance)']::text[], '2026-10-19T00:00:00Z', '{"gaps":["hud_state_page: hud.gov returned 403 and web search was unavailable; not sourced.","complaint_filing: Attorney General site (ag.state.mn.us) refused connections; no AG consumer complaint URL confirmed. The AG handbook is included with fetched=false.","court_self_help: mncourts.gov returned 403; court-authored LawHelpMN page used, with the mncourts forms URL in its notes.","rent_regulation: Minneapolis''s status (2021 voter authorization, no ordinance) is not verified from an official page in this session.","rental_assistance: no time-limited statewide emergency rental assistance program found live; ongoing state programs listed instead."],"rentRegulationCorrections":[{"correction":"Minor, lower confidence. The summary credits ''partial vacancy decontrol'' to the amendment effective June 13, 2025. City pages say the ordinance was amended in September 2022 (effective Jan 1, 2023) and May 2025 (effective June 13, 2025), and do not say which change came when. Contemporaneous reporting (from general knowledge, not re-verified this session) places the CPI+8% just-cause vacancy decontrol in the 2022 amendments. Suggested wording: ''amended effective Jan. 1, 2023 and June 13, 2025''. Separately, Minneapolis is listed but has no rent stabilization ordinance; the city Renters page has no rent stabilization content. Either drop it from localJurisdictions or label it ''authorized by voters in 2021, no ordinance in effect''.","sourceUrl":"https://www.stpaul.gov/departments/safety-inspections/rent-buy-sell-property/rent-stabilization/landlords"}]}'::jsonb),
  ('adb79473-5156-563a-abfe-9496be848999', 'MS', 'Mississippi', 'state', 'Mississippi Residential Landlord and Tenant Act, Miss. Code Ann. §§ 89-8-1 to 89-8-29 (eviction/removal of tenants: Miss. Code Ann. §§ 89-7-1 to 89-7-125)', false, 'unknown', 'Mississippi has no statewide rent cap. The Residential Landlord and Tenant Act published by the Attorney General (as amended through 2018) does not regulate rent levels; a state statute preempting local rent control has not been confirmed.', 'https://attorneygenerallynnfitch.com/wp-content/uploads/2021/07/Residential-Landlord-and-Tenant-Act.pdf', '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":["Statute section deep links: the official Mississippi Code is reachable only through the LexisNexis public-access app linked from the Legislature, which needs JavaScript and has no stable section URLs. Justia (the allowed fallback) returned a Cloudflare 403. The AG''s PDF of the Act is the best fetched substitute; key sections are §§ 89-8-15, 89-8-17, 89-8-21, 89-8-23 and 89-7-27.","HUD state tenant-rights page: hud.gov returned Cloudflare 403 to every automated request, and no official page found in this session linked the current Mississippi tenant-rights URL.","Court self-help: courts.ms.gov (Supreme Court/AOC) returned HTTP 500 errors on every request, so the judiciary''s landlord-tenant pages and the free code research page (courts.ms.gov/research/research.php) could not be confirmed.","State fair-housing agency: none identified; complaints appear to go to HUD FHEO (Jackson office).","Rental assistance: no live statewide emergency rental assistance program was found on the Mississippi Home Corporation site.","Rent-control preemption: could not be confirmed from an official source. WebSearch was unavailable (session search budget used up) and the code is not deep-linkable.","Code enforcement: housing code enforcement is local; no statewide agency page was found."],"rentRegulationCorrections":[{"correction":"No factual error found. The AG guide is a 2018 compilation (as amended through the 2018 session) with no rent-level regulation, which matches the summary. localRentControlPreempted remains ''unknown'': neither a preemption statute nor its absence could be confirmed, because WebSearch was exhausted and the Code is only on a JavaScript-only LexisNexis viewer. Resolve this before shipping rather than displaying ''unknown''.","sourceUrl":"https://attorneygenerallynnfitch.com/wp-content/uploads/2021/07/Residential-Landlord-and-Tenant-Act.pdf"}]}'::jsonb),
  ('2e3dac1f-b72a-5c26-9a22-ced380190a8a', 'MO', 'Missouri', 'state', 'Mo. Rev. Stat. chs. 441 (Landlord and Tenant), 534 (Forcible Entry and Unlawful Detainer) and 535 (Landlord-Tenant Actions; § 535.300 security deposits)', false, 'yes', 'Missouri has no statewide rent cap. RSMo § 441.043 bars counties and municipalities from regulating the amount of rent charged for private residential property.', 'https://revisor.mo.gov/main/OneSection.aspx?section=441.043', '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":["Statute deep links: revisor.mo.gov (the official RSMo site) refused all automated connections from this session (ECONNREFUSED or a ''Web Site Blocked'' page), and Justia returned a Cloudflare 403. Section links for § 441.234 (repair-and-deduct), § 535.300 (security deposits), chs. 534/535 (eviction) and § 441.043 (rent control) are therefore not listed.","Rent-control preemption: the § 441.043 statement comes from prior knowledge and could not be re-verified this session; check the statute text before publishing.","Court self-help: courts.mo.gov returned 403 or timed out, so the Missouri Courts landlord-tenant self-help pages could not be opened.","HUD state tenant-rights page: hud.gov blocked automated access (Cloudflare 403); only the general HUD Missouri page URL was confirmed, and only as a link from MHDC.","Health and safety: health.mo.gov (DHSS lead/mold pages) returned 403; only the federal EPA lead-disclosure page is listed.","Rental assistance: no live statewide emergency rental assistance program found.","Retaliation and late fees: no official Missouri page covering them was reached; the AG handbook does not address them.","Statewide Missouri Judiciary landlord-tenant self-help page: courts.mo.gov returned HTTP 403 to every fetch, and the search budget ran out before another route turned up. The Missouri Supreme Court''s 2010 order approving self-represented forms covers family-law cases only, not landlord-tenant, so these forms are issued circuit by circuit (16th Circuit added above)."],"rentRegulationCorrections":[{"correction":"No factual error was confirmed, but the claim is unverified and its sourceUrl does not support it. The summary rests on RSMo 441.043, yet sourceUrl is only the Revisor homepage, which was also geo-blocked here, so the statute text was never opened. The AG''s September 2025 handbook does not mention rent-control preemption. Before shipping, replace sourceUrl with the section page (expected pattern https://revisor.mo.gov/main/OneSection.aspx?section=441.043, not opened here) and confirm the text from a US network.","sourceUrl":"https://revisor.mo.gov/main/Home.aspx"}]}'::jsonb),
  ('8ff190f4-888d-5c45-b40a-8fb70f4d3bb5', 'MT', 'Montana', 'state', 'Montana Residential Landlord and Tenant Act of 1977, Mont. Code Ann. Title 70, ch. 24; Residential Tenants'' Security Deposits, Title 70, ch. 25; Forcible Entry and Detainer, Title 70, ch. 27', false, 'yes', 'Montana has no statewide rent cap. MCA 7-1-111(26) denies local self-government units any power to control the amount of rent charged for private residential or commercial property, and 7-1-111(13) bars local regulation of landlords beyond Title 70, chapters 24, 25 and 33; the section was last amended in 2025 (Ch. 537, L. 2025).', 'https://mca.legmt.gov/bills/mca/title_0070/chapter_0010/part_0010/section_0110/0070-0010-0010-0110.html', '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":["HUD state tenant-rights page: hud.gov returned Cloudflare 403 to all automated requests, and no Montana official page found in this session linked the current HUD Montana tenant-rights URL.","Attorney General / consumer protection: dojmt.gov (Office of Consumer Protection) returned Cloudflare 403, so its landlord-tenant page and complaint form could not be confirmed.","Official tenant handbook: the only state-hosted handbooks are 2010 court/MLSA documents; no current state-agency guide was found.","Health and safety: the DPHHS Environmental Health page has no lead, mold or bed-bug housing content, so only federal EPA pages are listed.","Late fees: no Montana statute section on residential late fees was identified in chapter 24.","Rental assistance: no general emergency rental assistance program is currently listed."],"rentRegulationCorrections":[]}'::jsonb),
  ('4fe886d6-7760-56e1-9fcf-ee983e80fed0', 'NE', 'Nebraska', 'state', 'Nebraska Uniform Residential Landlord and Tenant Act, Neb. Rev. Stat. §§ 76-1401 et seq. (range linked by the Judicial Branch as 76-1401 to 76-14,111); forcible entry and detainer, Neb. Rev. Stat. §§ 25-21,219 to 25-21,235', false, 'unknown', 'Nebraska has no statewide rent cap. Under its Uniform Residential Landlord and Tenant Act, rent may change in a periodic tenancy with at least 30 days'' written notice (Neb. Rev. Stat. § 76-1414, per Legal Aid of Nebraska). No local rent control ordinance is known, and a preemption statute has not been confirmed.', 'http://nebraskalegislature.gov/laws/search_range_statute.php?begin_section=76-1401&end_section=76-14,111', '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":["Statute pages: nebraskalegislature.gov refused or timed out on every automated connection (WebFetch and curl). Statute URLs are listed only where an official Judicial Branch page links them (fetched=false). Individual section links (e.g., § 76-1416, § 76-1419, § 76-1425, § 76-1439) are not listed because none could be verified.","Official state guide: no state-agency or court-published Nebraska landlord-tenant handbook was found. The AG consumer site has no landlord-tenant content; the Legal Aid of Nebraska 2025 handbook is the best available.","HUD state tenant-rights page: hud.gov returned Cloudflare 403, and no official Nebraska page found in this session linked it.","Rent-control preemption: could not be confirmed either way from an official source (legislature site blocked; WebSearch budget used up).","Rental assistance: no live statewide emergency rental assistance program was found; NIFA''s renters page only points to Nebraska.findhelp.com.","Health and safety: dhhs.ne.gov refused automated connections, so state lead/mold/housing pages could not be confirmed.","official_guide: no Nebraska state agency, court or bar publishes a landlord-tenant handbook. The AG consumer-protection resources page (protectthegoodlife.nebraska.gov/resources) and the Judicial Branch renter self-help page both send users to Legal Aid of Nebraska''s Landlord and Tenant Handbook, which is already listed. The Nebraska State Bar''s Find-a-Lawyer guides include no landlord-tenant guide. UNL Extension offers only the 2011 RentWise Facilitator''s Manual (CC435), a renter-education teaching curriculum rather than a guide to the law."],"rentRegulationCorrections":[]}'::jsonb),
  ('c713835c-5682-519f-9a42-7cc3fbe92230', 'NV', 'Nevada', 'state', 'Nevada Revised Statutes Chapter 118A, Landlord and Tenant: Dwellings (NRS 118A); summary eviction procedure in NRS Chapter 40 (e.g., NRS 40.251, 40.253, 40.254)', false, 'unknown', 'Nevada has no statewide rent cap and no known local rent control. NRS 118A.300 sets the written notice required before a rent increase; see the statute for the current notice period.', 'https://www.leg.state.nv.us/NRS/NRS-118A.html', '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":["hud_state_page: hud.gov returns HTTP 403 to automated fetches and the session''s web-search budget ran out, so the current HUD Nevada tenant-rights URL could not be confirmed.","official_guide: no state-agency tenant or landlord handbook was found. housing.nv.gov and ag.nv.gov return ''Request Rejected'' to automated requests, and search was unavailable.","statute (eviction): no confirmed deep link to NRS Chapter 40 (summary eviction, NRS 40.251-40.254) because leg.state.nv.us blocks bots. Justia also returned 403.","statute (security deposit / rent increase / late fees): anchors for NRS 118A.242, 118A.300 and 118A.210 were not found on any linking page, so the chapter link is used instead.","legal_aid_directory (LawHelp network): nevadalawhelp.org returned a Cloudflare 403 and could not be verified.","complaint_filing: the Attorney General consumer-protection complaint page could not be reached (WAF).","health_safety (statewide): no state-agency lead, mold or housing-code page for renters was found. The DPBH homepage has no housing links.","Statewide government-published landlord-tenant handbook (e.g. Nevada Supreme Court Access to Justice Commission handbook on nvcourts.gov, NV Attorney General or NV Housing Division guides): nvcourts.gov, ag.nv.gov, housing.nv.gov and leg.state.nv.us all returned 403/''Request Rejected'' to automated fetches, and the WebSearch budget for this session was exhausted, so none could be opened; the Clark County Law Library guide is the best verified substitute. The State Bar of Nevada''s public brochure list was checked and has no landlord-tenant brochure."],"rentRegulationCorrections":[{"correction":"I could not confirm the 60-day rent-increase notice. Nevada Legal Services and LACSN (''Tenants, Know Your Rights'') both say 60 days. However, an unofficial mirror of NRS 118A.300 captured 2025-05-26 reads 45 days'' written notice, or 15 days for periodic tenancies shorter than one month. The official text on leg.state.nv.us is behind Cloudflare and could not be checked, and the search budget ran out. Do not state 60 days as fact until the official NRS 118A.300 is read. Attribute the figure to the source, or link the statute without quoting a number.","sourceUrl":"https://nevada.public.law/statutes/nrs_118a.300"}]}'::jsonb),
  ('fadf2291-a25a-53f2-84bf-ff7f7cd09c24', 'NH', 'New Hampshire', 'state', 'N.H. RSA Chapter 540 (Actions Against Tenants) and RSA Chapter 540-A (Prohibited Practices and Security Deposits); minimum housing standards at RSA 48-A:14', false, 'unknown', 'New Hampshire has no statewide rent cap. According to 603 Legal Aid, rent increases for tenants without a lease are not limited in amount but need 30 days'' written notice (60 days in manufactured housing parks). No municipal rent control ordinance is known.', 'https://www.603legalaid.org/self-help-articles/housing/tenants/leases-rent-security-deposits/rent-increases/', '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":["hud_state_page: hud.gov returns HTTP 403 to automated fetches and the web-search budget ran out, so the current HUD New Hampshire tenant-rights URL could not be confirmed.","official_guide: no state-published (AG or Judicial Branch) landlord-tenant handbook could be found or opened. doj.nh.gov and courts.nh.gov return 403 Access Denied, and search was unavailable.","statute: every NH statute URL is fetched=false because gc.nh.gov and gencourt.state.nh.us reset automated connections. The URLs were taken from links on 603 Legal Aid pages. No confirmed link was found for the RSA 540 chapter index (eviction procedure, RSA 540:2-540:3) or for RSA 540:13-a (retaliation).","complaint_filing: the NH DOJ Consumer Protection complaint page could not be reached (403).","legal_aid_directory (LawHelp network): nhlegalaid.org loads only a JavaScript redirect and its content could not be read, so 603 Legal Aid is used instead.","code_enforcement: no state code-enforcement page was found. Housing standards are enforced by local health and code officers under RSA 48-A.","General (not program-specific) state-published NH landlord-tenant handbook (e.g. NH DOJ Consumer Protection guide or a NH Judicial Branch landlord/tenant guide): doj.nh.gov and courts.nh.gov returned HTTP 403 to every automated fetch this session, and the WebSearch budget was exhausted, so none could be opened. NH Legal Assistance''s pamphlet list (nhla.org) has only a manufactured-housing tenant pamphlet, and the NH Bar public pages have no landlord-tenant guide."],"rentRegulationCorrections":[]}'::jsonb),
  ('0fa73d0c-6f9d-50b0-a777-47750822f04b', 'NJ', 'New Jersey', 'state', 'N.J.S.A. 2A:18-61.1 et seq. (Anti-Eviction Act) within N.J.S.A. 2A:18-53 to -84 (summary dispossess); Security Deposit Law N.J.S.A. 46:8-19 to -26; Truth-in-Renting Act N.J.S.A. 46:8-43 to -50', false, 'no', 'New Jersey has no statewide rent cap; municipalities may adopt rent control or rent leveling ordinances. DCA''s 2026 Rent Control Survey (updated May 20, 2026) lists 120 of 564 municipalities with an ordinance on record. N.J.S.A. 2A:42-84.1 to -84.6 exempt multiple dwellings (4+ units) built after the 1987 act from municipal rent limits for up to 30 years after completion, or the initial mortgage term if shorter.', 'https://www.nj.gov/dca/home/misc/Rent_Control_Survey.xlsx', array['Jersey City','Newark','Hoboken','Elizabeth','Paterson','Trenton','Bayonne','Asbury Park','Atlantic City','Belleville']::text[], '2026-10-19T00:00:00Z', '{"gaps":["hud_state_page: hud.gov returns HTTP 403 to automated fetches and the web-search budget ran out, so the current HUD New Jersey tenant-rights URL could not be confirmed.","court_self_help: njcourts.gov returns 403 (Cloudflare) to automated requests and no current Landlord/Tenant self-help URL was found on any linking page. The DCA NJ Eviction Guide is listed instead.","statute deep links: the NJ Legislature''s statutes database has no stable per-section URLs, and Justia returned 403. DCA''s official reprints (2008-2010) are used and may not reflect later amendments.","complaint_filing (landlord-tenant): no AG or Consumer Affairs complaint channel specific to landlord-tenant matters was found. Discrimination complaints go to the DCR, and code complaints to the DCA Bureau of Housing Inspection.","legal_aid_directory: LSNJ sites (lsnjlaw.org, lsnjlawhotline.org) block automated fetches, so they are listed with fetched=false."],"rentRegulationCorrections":[{"correction":"The new-construction exemption is cited to the wrong section and stated too broadly. The operative exemption is N.J.S.A. 2A:42-84.2; 2A:42-84.5 is the legislative-intent and anti-impairment section, although DCA''s Truth in Renting does cite 84.5. The exemption covers only ''multiple dwellings'', meaning 4 or more units and excluding senior-citizen housing, built under permits issued after P.L.1987, c.153 took effect. It runs for the shorter of two periods: the amortization period of the initial mortgage, or 30 years from completion. With no initial mortgage it is 30 years. Suggested wording: ''N.J.S.A. 2A:42-84.1 to -84.6 exempt multiple dwellings (4+ units) constructed after the 1987 act from municipal rent-increase limits for up to 30 years after completion (or the initial mortgage amortization period, if shorter).'' The 120-of-564 count and the 2026-05-20 file date are confirmed.","sourceUrl":"https://www.nj.gov/dca/codes/publications/pdf_lti/new_const_m_dwell_law.pdf"}]}'::jsonb),
  ('a10a72da-8f1b-551d-85e0-8e1b6c23720f', 'NM', 'New Mexico', 'state', 'Uniform Owner-Resident Relations Act, NMSA 1978, §§ 47-8-1 to 47-8-52; Rent Control Prohibition, NMSA 1978, § 47-8A-1', false, 'yes', 'NMSA 1978, § 47-8A-1 (Laws 1991, ch. 23) bars political subdivisions and home-rule municipalities from enacting ordinances that control rental rates on privately owned property. Publicly subsidized reduced-rent housing is excepted. There is no statewide cap, and the compiled section shows no amendment since 1991. In a separate change, Laws 2025, ch. 122 (effective June 20, 2025) lowered the maximum late fee to 5% of rent (§ 47-8-15) and added private enforcement (§ 47-8-48).', 'https://nmonesource.com/nmos/nmsa/en/item/4408/index.do', '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":["hud_state_page: hud.gov returns HTTP 403 to automated fetches and the web-search budget ran out, so the current HUD New Mexico tenant-rights URL could not be confirmed.","statute section deep links: NMOneSource has no stable per-section URLs, nmlegis.gov returned 403, and Justia/LII returned 403, so section entries share the chapter link.","fair_housing (state agency page): the NM Workforce Solutions Human Rights Bureau site (dws.state.nm.us) returns 403. The Housing New Mexico fair housing page with Bureau contacts is used instead.","health_safety / code_enforcement: no state-agency page on lead, mold or housing-code enforcement for renters was found in this session.","official_guide (AG): no current NM Department of Justice landlord-tenant guide was found. The Housing New Mexico/NMLA Renter''s Guide is used instead."],"rentRegulationCorrections":[]}'::jsonb),
  ('de4c7246-583e-596c-b297-212a455cfd6a', 'NY', 'New York', 'state', 'N.Y. Real Property Law Article 7 (Landlord and Tenant, §§ 220–238-a) with RPAPL Article 7 (Summary Proceedings) and RPL Article 6-A (Good Cause Eviction Law)', false, 'no', 'New York has no statewide rent cap. Rent stabilization applies in NYC and in localities that adopted ETPA (Nassau, Rockland and Westchester municipalities and the City of Kingston). The NYC Rent Guidelines Board adopted Order #58 on June 25, 2026, setting 0% for 1- and 2-year leases starting Oct 1, 2026 through Sept 30, 2027. The Good Cause Eviction Law (signed April 20, 2024) applies in NYC and in municipalities that opt in, and treats increases above the local rent standard (CPI + 5%, capped at 10%) as presumptively unreasonable for covered units.', 'https://hcr.ny.gov/good-cause-eviction', array['New York City (rent stabilization/rent control; Good Cause Eviction mandatory)','ETPA, Nassau County: Baxter Estates, Cedarhurst, Floral Park, Flower Hill, Freeport, Glen Cove, Great Neck, Great Neck Plaza, Hempstead (village), North Hempstead (town), Long Beach, Lynbrook, Mineola, Rockville Centre, Russell Gardens, Thomaston','ETPA, Rockland County: Town of Haverstraw, Village of Spring Valley','ETPA, Westchester County: multiple municipalities incl. Croton-on-Hudson, Dobbs Ferry, Eastchester, Greenburgh, Harrison, Hastings-on-Hudson, Irvington, Larchmont, Mamaroneck, Mount Kisco, Mount Vernon, New Rochelle, Ossining (partial list per HCR Fact Sheet #8, 11/2024)','ETPA: City of Kingston (upheld by NY Court of Appeals, June 2025)','Good Cause Eviction opt-ins as of May 4, 2026 (DHCR notice): Cities of Albany, Beacon, Binghamton, Hudson, Ithaca, Kingston, Middletown, New Rochelle, Newburgh, Poughkeepsie, Rochester, White Plains; Towns of Fishkill and Poughkeepsie; Villages of Catskill, Croton-on-Hudson, New Paltz, Nyack, Tarrytown']::text[], '2026-10-19T00:00:00Z', '{"gaps":["Web search budget for the session was exhausted at the start of this task; pages were reached only by fetching official sites directly and following their links.","hud_state_page: hud.gov returned HTTP 403 to every automated request and the current New York ''Tenant Rights, Laws and Protections'' URL could not be confirmed by search.","court_self_help: nycourts.gov (CourtHelp housing pages and NYC Housing Court) returned HTTP 403; candidate https://www.nycourts.gov/courthelp/Housing/index.shtml is unverified and was not included.","rental_assistance: otda.ny.gov reset every connection, so no current OTDA emergency/rental assistance page could be confirmed.","health_safety: health.ny.gov (NYS DOH lead and mold pages) returned HTTP 403; the EPA federal lead page and NYC HPD were used instead.","GOL § 7-107 (deposits for rent-stabilized units) was not opened.","category: court_self_help (verified) - the NY court system''s own self-help pages exist and are listed above, but every nycourts.gov URL (including the legacy ww2/courthelp paths) returns a Cloudflare JS challenge (HTTP 403) to automated fetches, so none could be opened. They need a manual browser check, and no non-judiciary substitute qualifies for this category."],"rentRegulationCorrections":[]}'::jsonb),
  ('ae835138-8228-5243-87bb-b8135f8f7be7', 'NC', 'North Carolina', 'state', 'N.C. Gen. Stat. Chapter 42 (Landlord and Tenant), incl. Art. 5 Residential Rental Agreements Act (§ 42-38 et seq.) and Art. 6 Tenant Security Deposit Act', false, 'yes', 'North Carolina has no statewide rent cap. G.S. 42-14.1 bars counties and cities from regulating rent on private rental property, with a carve-out for government-owned and subsidized properties. S.L. 2024-47 amended 42-14.1 to also bar local ordinances that stop landlords from refusing tenants whose income includes federal housing assistance, and it revised the G.S. 42-46 late-fee rules.', 'https://www.ncleg.gov/EnactedLegislation/Statutes/HTML/BySection/Chapter_42/GS_42-14.1.html', '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":["Web search budget was exhausted at the start of this task; pages were reached only by fetching official sites directly and following their links.","statute: ncleg.gov/ncleg.net blocks automated fetching (HTTP 403), so every NC statute link is fetched=false. Each was confirmed as a live link on UNC SOG, LawHelpNC or NC DOJ pages. A Chapter 42 index page URL could not be confirmed.","rent increase notice: no separate NC statute on rent-increase notice was identified; rent_increase is covered only through G.S. 42-14.1.","hud_state_page: hud.gov returned HTTP 403 and the current NC tenant-rights page URL could not be confirmed by search.","court_self_help: nccourts.gov returned HTTP 403; the two court URLs included are link-confirmed only.","official_guide: the NC DOJ repair-duties guide is dated 2018 (PDF metadata). NC Real Estate Commission brochures could not be opened (HTTP 403).","complaint_filing: NC DOJ has no landlord-tenant-specific complaint form; only the general consumer complaint form is listed.","health_safety / code_enforcement: no state-level NC page on housing-code enforcement, lead, mold or pests was sourced, since enforcement is local. The federal EPA page is included."],"rentRegulationCorrections":[]}'::jsonb),
  ('2032a67a-3c26-53b8-87d0-3a6ae7de20cb', 'ND', 'North Dakota', 'state', 'N.D. Cent. Code ch. 47-16 (Leasing of Real Property) and ch. 47-32 (Eviction)', false, 'yes', 'North Dakota has no statewide rent cap. N.D.C.C. § 47-16-02.1 bars political subdivisions from enacting or enforcing ordinances that control rent on private residential or commercial property.', 'https://www.ndlegis.gov/cencode/t47c16.pdf#nameddest=47-16-02p1', '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":["Web search budget was exhausted at the start of this task; pages were reached only by fetching official sites directly and following their links.","hud_state_page: hud.gov returned HTTP 403 and the current ND tenant-rights page URL could not be confirmed by search.","court_self_help: ndcourts.gov returned HTTP 403. Only the tenant eviction page is link-confirmed; a landlord-side eviction self-help page was not confirmed.","complaint_filing: the ND Attorney General states it cannot take or mediate landlord/tenant complaints, and no other state complaint channel for general landlord-tenant disputes was found (fair housing complaints go to NDDOLHR).","retaliation / late fees: no general retaliation section (only a domestic-violence-related anti-retaliation provision in § 47-16-17.1) and no late-fee section were found in ch. 47-16. The AG page says late fees must be stated in the lease.","health_safety / code_enforcement: no state-level ND page on housing-code enforcement, mold or pests was sourced, since enforcement is local. The federal EPA lead page is included."],"rentRegulationCorrections":[]}'::jsonb),
  ('5365f622-a1ce-5b0d-b511-4b554b23ec22', 'OH', 'Ohio', 'state', 'Ohio Rev. Code Chapter 5321 (Landlords and Tenants) and Chapter 1923 (Forcible Entry and Detainer)', false, 'unknown', 'Ohio has no statewide rent cap or rent control law; Ohio Legal Help notes that landlords can raise rent with proper notice. Whether state law preempts local rent control has not been confirmed.', 'https://www.ohiolegalhelp.org/topic/ohio-landlord-tenant-law', '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":["Web search budget was exhausted at the start of this task. In addition, every Ohio state government site tried (codes.ohio.gov, ohioattorneygeneral.gov, supremecourt.ohio.gov, legislature.ohio.gov, ohiohome.org, civ.ohio.gov, odh.ohio.gov) refused connections or returned errors to all automated requests, including home pages.","statute: deep links for ORC 5321.04 (landlord obligations, including entry notice), 5321.07 (rent escrow), 5321.02 (retaliation), Chapter 5321 index, and Chapter 1923 / 1923.04 (forcible entry and detainer, 3-day notice) could not be verified. Only 5321.16 and 5321.15 are link-confirmed.","official_guide: no Ohio Attorney General or other state-published landlord-tenant guide could be opened or link-confirmed.","hud_state_page: hud.gov returned HTTP 403 and the current Ohio tenant-rights page URL could not be confirmed by search.","court_self_help: no Supreme Court of Ohio statewide eviction self-help or forms page could be verified; only local housing courts (Cleveland, Toledo, Franklin County) are included.","complaint_filing: the Ohio Attorney General consumer complaint page was unreachable.","rental_assistance: Ohio Housing Finance Agency and Ohio Department of Development pages were unreachable; no state rental assistance page is included.","health_safety: Ohio Department of Health lead pages were unreachable; the federal EPA page is included instead.","rent_regulation: whether Ohio statute preempts local rent control could not be verified from an official source (marked unknown).","Ohio Attorney General landlord-tenant guide - no such publication on ohioattorneygeneral.gov could be found (search only surfaced a third-party copy that matches Pennsylvania''s AG guide), and ohioattorneygeneral.gov refused the connection when opened, so the OSBA pamphlet is used as the statewide official guide instead"],"rentRegulationCorrections":[]}'::jsonb),
  ('d6860c94-18bb-511b-9783-417e7c291d88', 'OK', 'Oklahoma', 'state', 'Oklahoma Residential Landlord and Tenant Act, Okla. Stat. tit. 41, §§ 101-136 (eviction procedure: Okla. Stat. tit. 12, §§ 1148.1-1148.16, forcible entry and detainer)', false, 'yes', 'Oklahoma has no statewide rent cap. Okla. Stat. tit. 11, § 14-101.1 (added 1988) bars municipalities from enacting or enforcing ordinances that regulate rent on privately owned residential or commercial rental property, with exceptions for municipal property, subsidized-housing agreements and CDBG-assisted properties; the current compiled statute shows no 2024-2026 change.', 'https://www.oklegislature.gov/OK_Statutes/CompleteTitles/os11.pdf#page=78', '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":["court_self_help: The Oklahoma judiciary''s statute and self-help site (oscn.net) refused connections from this environment, so no official eviction self-help or forms page could be verified.","official_guide: No state-agency or AG landlord-tenant handbook was found. The OBA Young Adult Guide lease chapter is the closest official-bar resource. OKLaw.org (legal aid) blocked automated fetching.","hud_state_page: hud.gov blocks automated fetching (HTTP 403). Only the Oklahoma state-page URL could be confirmed by search; the per-state tenant-rights subpage URL could not be confirmed.","statute deep links: Per-section official pages exist only on OSCN, which was unreachable, and the Justia fallback blocked fetching. Section links therefore use #page fragments into the Legislature''s official full-title PDFs.","complaint_filing: The AG consumer complaint page does not state that landlord-tenant disputes are accepted.","retaliation/late fees: No standalone anti-retaliation or late-fee section was found in the Residential Landlord and Tenant Act (Title 41).","The session''s shared WebSearch budget ran out partway through, which limited further discovery."],"rentRegulationCorrections":[]}'::jsonb),
  ('7a8bfc77-5823-5b68-9204-3f1d1f7563e7', 'OR', 'Oregon', 'state', 'Oregon Residential Landlord and Tenant Act, ORS chapter 90 (eviction procedure also in ORS 105.105 et seq.)', true, 'yes', 'Oregon caps annual rent increases statewide under ORS 90.323 and 90.324 at the lesser of 10% or 7% plus CPI. The Office of Economic Analysis set the cap at 9.5% for 2026 and 10% for 2027, and per ORS 90.324 as quoted by OEA, manufactured-dwelling facilities with more than 30 spaces are capped at 6%. ORS 91.225 prohibits local rent control, with listed exceptions.', 'https://www.oregon.gov/das/OEA/pages/rent-stabilization.aspx', '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":["Statute deep links: oregonlegislature.gov was unreachable from this environment and Justia blocked fetching, so section links use the free Public.Law ORS mirror (not Justia or LII). Swap them for the official chapter page if third-party mirrors are not acceptable.","official_guide: No dedicated state-agency landlord-tenant handbook was found. The OHCS Landlord & Tenant Resources page and Oregon Law Help (the Oregon State Bar''s landlord-tenant link redirects there) are the closest.","complaint_filing: No state complaint channel specific to private landlord-tenant disputes was found. Oregon DOJ consumer complaints do not list landlord-tenant, and the OHCS form covers only OHCS-monitored affordable housing.","rent_regulation: The 2026 and 2027 percentages come from the OEA page. Bill numbers for the 2023 (10% ceiling) and 2025 (6% for large manufactured-dwelling parks) changes were not verified in this session.","The session''s shared WebSearch budget ran out partway through."],"rentRegulationCorrections":[]}'::jsonb),
  ('d7ce91e1-146c-5365-9a89-c348b0a02330', 'PA', 'Pennsylvania', 'state', 'Landlord and Tenant Act of 1951 (Act 20 of 1951, P.L. 69), 68 P.S. § 250.101 et seq.', false, 'unknown', 'Pennsylvania has no statewide rent cap or rent stabilization law, and official sources describe no municipal rent control. An express state preemption provision has not been confirmed.', 'https://www.attorneygeneral.gov/wp-content/uploads/ConsumerTenant-Landlord-Guide.pdf', '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":["hud_state_page: hud.gov blocks automated fetching (HTTP 403), and the WebSearch budget ran out before the Pennsylvania tenant-rights page URL could be confirmed.","rental_assistance: The state Emergency Rental Assistance Program closed October 1, 2025 (pa.gov/agencies/dhs/resources/erap). PHFA (phfa.org) was unreachable, so no currently live statewide renter assistance page was verified.","statute: The official General Assembly sites were unreachable, so the Act PDF is listed as fetched=false (search-confirmed). Section-level deep links for repairs (no statutory repair-and-deduct; habitability rests on case law per the AG guide), deposits, eviction and the separate Rent Withholding Act could not be verified.","court_self_help: Statewide pacourts.us pages blocked automated fetching. Only Philadelphia Municipal Court pages were opened.","rent_regulation: No official source stating Pennsylvania''s rent-control or preemption status was found or verified.","code_enforcement: Housing code enforcement is municipal. Only Philadelphia L&I material was verified."],"rentRegulationCorrections":[]}'::jsonb),
  ('e8375018-6c97-5b7d-8731-3396670bf65d', 'RI', 'Rhode Island', 'state', 'Residential Landlord and Tenant Act, R.I. Gen. Laws ch. 34-18 (§ 34-18-1 et seq.)', false, 'unknown', 'Rhode Island has no statewide rent cap. Since June 24, 2024, R.I. Gen. Laws § 34-18-16.1 requires written notice at least 60 days before a rent increase (120 days for month-to-month tenants over 62). 2025 bills proposing a 4% annual cap were introduced; enactment has not been confirmed.', 'https://webserver.rilegislature.gov/Statutes/TITLE34/34-18/34-18-16.1.htm', '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":["statute: The chapter 34-18 index and sections on security deposits (§ 34-18-19), eviction for nonpayment (§ 34-18-35 and related), retaliation (§ 34-18-46) and repair-and-deduct (§ 34-18-30) could not be URL-verified. webserver.rilegislature.gov was unreachable and the WebSearch budget ran out; only §§ 34-18-16.1 and 34-18-22 were search-confirmed.","official_guide: The Department of Housing Landlord-Tenant Handbook page blocked automated fetching (HTTP 403), so its revision date and contents were not confirmed.","complaint_filing: The Attorney General site (riag.ri.gov) returned HTTP 403, so no AG consumer complaint page accepting landlord-tenant complaints was verified.","health_safety: RI Department of Health lead and healthy-housing pages (health.ri.gov) and the Housing Resources Commission lead pages blocked automated fetching. Only the rental registry link and the court affidavit form referencing lead certificates were confirmed.","hud_state_page: The HUD tenant-rights subpage for Rhode Island was not confirmed. Only the state landing page URL was.","rent_regulation: Whether the 2025 rent-cap bills or 2026 security-deposit bills (H 8113/S 2973, H 7130) were enacted, and whether any preemption exists, could not be verified."],"rentRegulationCorrections":[]}'::jsonb),
  ('2e6b48ef-e7c7-5d76-b03f-60ba847409de', 'SC', 'South Carolina', 'state', 'South Carolina Residential Landlord and Tenant Act, S.C. Code Ann. Title 27, Chapter 40 (§ 27-40-10 et seq.); ejectment procedure in Title 27, Chapter 37', false, 'yes', 'South Carolina has no statewide rent cap, and S.C. Code § 27-39-60 (1985 Act No. 184) bars counties and municipalities from enacting, maintaining, or enforcing any ordinance that regulates the amount of rent for privately owned residential or commercial rental property. The official code text showed no 2024-2026 amendment to this section or to Chapter 40 (latest history entries date to 1999).', 'https://www.scstatehouse.gov/code/t27c039.php', '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":["hud_state_page: HUD''s South Carolina tenant-rights page could not be verified; hud.gov refused automated requests (403/connection refused) and the session''s web-search budget was exhausted before a search could confirm the current URL.","official_guide: no state-agency tenant/landlord handbook could be verified; the SC Department of Consumer Affairs site (consumer.sc.gov) returned 403 to every request.","complaint_filing: SC Department of Consumer Affairs complaint pages were blocked (403); the SC Attorney General''s consumer pages do not address landlord-tenant matters.","court_self_help: SC Judicial Branch magistrate-court and self-help pages returned HTTP 406; LawHelp.org/SC self-help forms are temporarily disabled by SC Legal Services.","rental_assistance: SC Housing (schousing.sc.gov / schousing.com) returned 403 or refused connections; no live statewide emergency rental assistance program could be confirmed.","fair_housing: the SC Human Affairs Commission''s HTML complaint page could not be opened (403); only a brochure PDF found via search is listed.","health_safety/code_enforcement: SC Department of Public Health and Department of Environmental Services sites returned 403; only the federal EPA lead-disclosure page is listed.","statute deep links: scstatehouse.gov has no per-section anchors and the Justia fallback returned 403, so section entries point to the chapter page."],"rentRegulationCorrections":[]}'::jsonb),
  ('baf97aeb-d3e5-5165-88bc-0020fea83048', 'SD', 'South Dakota', 'state', 'S.D. Codified Laws ch. 43-32 (Lease of Real Property); eviction procedure in SDCL ch. 21-16 (Forcible Entry and Detainer)', false, 'yes', 'South Dakota has no statewide rent cap. SDCL 6-1-13 prohibits local governments from enacting or enforcing measures that control rent on private residential property. Related recent changes: SL 2024, ch 75 (eviction procedure) and SL 2026, ch 179 (deposit return period).', 'https://sdlegislature.gov/Statutes?Statute=6-1-13', '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":["hud_state_page: HUD''s South Dakota tenant-rights page could not be verified; hud.gov refused automated requests and the session''s web-search budget was exhausted.","health_safety/code_enforcement: no South Dakota state-agency page on lead, mold, or housing-code enforcement was located; only the federal EPA lead-disclosure page is listed.","complaint_filing: the Attorney General complaint form is general consumer intake and does not explicitly accept landlord-tenant disputes.","rental_assistance: no live statewide emergency rental assistance program was found; SD Housing lists vouchers and security deposit assistance only.","official_guide currency: the Attorney General''s guide and Fast Facts page predate SL 2024, ch 75 and SL 2026, ch 179."],"rentRegulationCorrections":[]}'::jsonb),
  ('b043128c-61a5-5afd-a104-7d84bf5d137a', 'TN', 'Tennessee', 'state', 'Uniform Residential Landlord and Tenant Act, Tenn. Code Ann. Title 66, Chapter 28 (§ 66-28-101 et seq.), which applies only in counties above a population threshold; detainer (eviction) procedure in Tenn. Code Ann. Title 29, Chapter 18', false, 'yes', 'Tennessee has no statewide rent cap. Tenn. Code Ann. § 66-35-102 bars local governments from controlling the amount of rent on private residential property.', 'https://www.lexisnexis.com/hottopics/tncode/', '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":["statute deep links: the official Tennessee Code is published through LexisNexis''s free-access JavaScript app, which cannot be deep-linked or fetched; the Justia fallback returned 403, and capitol.tn.gov refused connections.","official_guide: no official state tenant/landlord handbook (AG, THDA, or court) was found; the AG consumer pages do not cover landlord-tenant topics.","court_self_help: tncourts.gov serves a JavaScript bot challenge, so no Tennessee judiciary landlord-tenant/detainer self-help page could be opened.","rental_assistance: THDA''s statewide emergency rental assistance program ended July 31, 2025; only the HCV voucher program is listed.","health_safety/code_enforcement: no Tennessee state-agency page on lead, mold, or bed bugs for renters was located; only the federal EPA page is listed.","rent_regulation: Tenn. Code Ann. § 66-35-102 text could not be opened from an official source in this session.","hud_state_page: listed from search results only (fetched=false)."],"rentRegulationCorrections":[]}'::jsonb),
  ('e4988004-f718-5a50-8128-d8374a7b491c', 'TX', 'Texas', 'state', 'Texas Property Code Chapter 92 (Residential Tenancies); eviction procedure in Texas Property Code Chapter 24 (Forcible Entry and Detainer)', false, 'partial', 'Texas has no statewide rent cap; Local Government Code § 214.902 allows a municipality to adopt rent control only if it finds a disaster-related housing emergency and the governor approves the ordinance. Separately, S.B. 38 (2025, effective January 1, 2026) added Property Code § 24.0043, which provides that only the legislature may modify or suspend the statutory eviction procedures.', 'https://statutes.capitol.texas.gov/Docs/LG/htm/LG.214.htm#214.902', '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":["hud_state_page: HUD''s Texas ''Tenant Rights, Laws and Protections'' subpage could not be confirmed; hud.gov refused automated requests and the web-search budget was exhausted. Only the search-confirmed renting page is listed.","court_self_help (judiciary): txcourts.gov returned 403, so the Texas Supreme Court''s eviction rules (TRCP 510, amended for 2026) and Judicial Branch pages could not be opened; TJCTC court-funded pages are listed instead.","fair_housing: the TWC Civil Rights Division site did not resolve from this environment; only a search-confirmed complaint-form PDF is listed (fetched=false).","rental_assistance: no live statewide emergency rental assistance program was found; Texas Rent Relief closed March 31, 2023, and TDHCA''s site returned 403.","official_guide: the State Bar of Texas tenant pamphlet linked from the AG page could not be reached (connection refused).","security_deposit legal-aid explainer: no TexasLawHelp deposit article was found by navigation; the statute and the AG page cover deposits."],"rentRegulationCorrections":[]}'::jsonb),
  ('aa3b6730-9718-52f5-aee4-3b59f9ead788', 'UT', 'Utah', 'state', 'Utah Fit Premises Act, Utah Code Title 57, Chapter 22; renter deposits, Utah Code Title 57, Chapter 17; forcible entry and detainer, Utah Code Title 78B, Chapter 6, Part 8 (78B-6-801 et seq.)', false, 'yes', 'Utah has no statewide rent cap. Utah Code 57-20-1 bars counties, cities and towns from enacting ordinances that control rents or fees on private residential property without the Legislature''s express approval.', 'https://le.utah.gov/xcode/Title57/Chapter20/57-20-S1.html', '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":["fair_housing: Utah Antidiscrimination and Labor Division (Labor Commission) fair housing page could not be verified; laborcommission.utah.gov returned HTTP 403 and no search confirmation was available (search budget exhausted).","complaint_filing: no attorney-general or consumer-protection intake for landlord-tenant complaints found; the Utah AG homepage has no landlord-tenant link and consumerprotection.utah.gov returned 403.","official_guide: no state-published tenant/landlord handbook found; the Utah courts self-help pages and the nonprofit Utah Housing Coalition toolkit are the closest equivalents.","health_safety: Utah DHHS/DEQ pages on lead, mold or radon could not be opened (HTTP 403 or connection refused).","statute: le.utah.gov and legacy.utcourts.gov refused all connections, so every Utah statute link is fetched=false; the chapter-level 57-22 URL and separate late-fee and retaliation sections were not confirmed.","rental_assistance: the state DWS housing/rental assistance page (jobs.utah.gov) returned 403; only a nonprofit program was verified.","official_guide (statewide): no state-, bar- or court-published Utah landlord-tenant handbook was found. The Utah State Bar''s UtahLegalHelp.org and the Utah Courts self-help pages have no such guide, so Salt Lake City''s Housing Stability guides are the closest official substitute. Web search was exhausted (session limit reached), so this may be incomplete.","fair_housing (verification): the Utah Labor Commission/UALD fair housing page is included with fetched=false because laborcommission.utah.gov returns HTTP 403 to automated fetches. It needs a manual browser check.","Utah Fair Housing Act statute text (Utah Code Title 57, Chapter 21) could not be opened: le.utah.gov and the legacy.utcourts.gov statute mirror refused connections during this session, and HUD''s FHEO pages (hud.gov) also returned 403."],"rentRegulationCorrections":[{"correction":"UNVERIFIED and possibly inaccurate: the claim that 57-20-1 was ''last amended in 2006 (H.B. 250)''. le.utah.gov was unreachable from the audit environment, so the section history could not be read. The sourceUrl is a version-pinned file stamped 1800-01-01 (C57-20-S1_1800010118000101), the base or unamended version in Utah''s code system, which conflicts with a 2006 amendment. Either the amendment claim is wrong, or the sourceUrl shows a superseded version. Drop the amendment-year detail unless confirmed, and pin the unversioned section URL (le.utah.gov/xcode/Title57/Chapter20/57-20-S1.html, not opened). The core statement (no statewide cap; local rent and fee control barred without legislative approval) is consistent with the statute''s known effect but was not re-read here.","sourceUrl":""}]}'::jsonb),
  ('51dd8695-b24a-570b-b7c7-b4f66bbd0da3', 'VT', 'Vermont', 'state', 'Residential Rental Agreements Act, 9 V.S.A. chapter 137 (9 V.S.A. 4451-4469a); ejectment, 12 V.S.A. chapter 169', false, 'unknown', 'Vermont has no statewide rent cap; 9 V.S.A. 4455 requires at least 60 days'' written notice of a rent increase, and VTLawHelp reports that Burlington requires 90 days'' notice. No express state preemption of local rent control and no 2024-2026 rent-cap enactment were identified in this research.', 'https://legislature.vermont.gov/statutes/section/09/137/04455', '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":["hud_state_page: hud.gov returned 403 and the Vermont-specific HUD tenant-rights URL could not be confirmed by search (search budget exhausted).","complaint_filing: the AG Consumer Assistance Program complaint page does not mention landlord-tenant complaints; no AG landlord-tenant intake was found.","rental_assistance: no statewide emergency rental assistance program currently live was found; ACCD points to Vermont State Housing Authority and 2-1-1.","court_self_help: vermontjudiciary.org returned 403, so the landlord-tenant page is fetched=false.","statute: legislature.vermont.gov refused connections, so all statute links are fetched=false; section URLs for 9 V.S.A. 4458 (withholding), 4459 (repair and deduct) and 4465 (retaliation) were not confirmed. Vermont has no separate late-fee statute section identified.","rent_regulation: no official source on local rent-control authority or 2024-2026 local changes (e.g., Burlington) could be verified."],"rentRegulationCorrections":[]}'::jsonb),
  ('15d46d54-5446-5754-aed1-751101c01ea4', 'VA', 'Virginia', 'state', 'Virginia Residential Landlord and Tenant Act, Va. Code 55.1-1200 to 55.1-1262 (Title 55.1, Chapter 12); unlawful entry and detainer, Va. Code 8.01-124 et seq.', false, 'partial', 'Virginia has no statewide rent cap. Va. Code 55.1-1201(E) states the VRLTA supersedes local ordinances concerning landlord-tenant relations and residential leasing (except mediation bodies and property-maintenance code enforcement) but does not expressly mention rent amounts; 2026 legislation (2026 c. 1066, HB 678) lengthens rent-increase notice for landlords with more than four units from 60 to 90 days effective July 1, 2027.', 'https://law.lis.virginia.gov/vacode/title55.1/chapter12/section55.1-1201/', '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":["hud_state_page: hud.gov returned 403 and the Virginia-specific HUD tenant-rights URL could not be confirmed by search (search budget exhausted).","complaint_filing: the Attorney General''s Consumer Protection Section states it does not accept landlord-tenant complaints; no other state complaint intake was found.","rental_assistance: no statewide renter or emergency rental assistance program currently live was found on DHCD or Virginia Housing pages (DHCD lists a crisis hotline directory; Virginia Housing lists Housing Choice Vouchers).","code_enforcement: housing code enforcement is through local building officials under the Virginia Maintenance Code; no statewide tenant-facing enforcement page was opened.","health_safety: no Virginia state page on mold or bed bugs in rentals was found (VRLTA 55.1-1215 covers mold disclosure)."],"rentRegulationCorrections":[]}'::jsonb),
  ('078a3e85-4dbd-52a0-b554-6656f2ee70a8', 'WA', 'Washington', 'state', 'Residential Landlord-Tenant Act, RCW 59.18; Forcible Entry and Forcible and Unlawful Detainer, RCW 59.12', true, 'partial', 'Since May 7, 2025 (2025 c 209, HB 1217), RCW 59.18.700 bars rent increases in a tenancy''s first 12 months and caps later increases in any 12-month period at the lesser of 7% plus CPI or 10%; Commerce publishes the annual cap (9.683% for 2026, 10% for 2027), and RCW 59.18.140 requires 90 days'' notice. RCW 35.21.830 still preempts city and town ordinances regulating rent amounts, with exceptions for publicly owned or managed and certain low-income housing.', 'https://app.leg.wa.gov/RCW/default.aspx?cite=59.18.700', '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":["hud_state_page: hud.gov returned 403 and the Washington-specific HUD tenant-rights URL could not be confirmed by search (search budget exhausted).","court_self_help: courts.wa.gov refused connections and info.courts.wa.gov failed DNS lookup, so both court resources are fetched=false; the official eviction forms index page could not be confirmed.","rental_assistance: no tenant-facing statewide rent assistance program was found; Commerce states its programs do not provide direct assistance and directs people to local Coordinated Entry."],"rentRegulationCorrections":[]}'::jsonb),
  ('1286fae9-12dc-5fd7-9557-7ecf19ccb100', 'WV', 'West Virginia', 'state', 'W. Va. Code ch. 37, art. 6 (Landlord and Tenant) and art. 6A (Security Deposits); W. Va. Code ch. 55, art. 3A (Summary Relief for Wrongful Occupation of Residential Rental Property)', false, 'unknown', 'West Virginia has no statewide rent cap and no known local rent control ordinance. An express state preemption of local rent control has not been confirmed.', 'https://code.wvlegislature.gov/?chap=37&art=6', '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":["Web search was unavailable for this entire session (session search budget exhausted); all URLs were verified by opening them or via links on official/legal-aid pages.","hud_state_page: hud.gov returns HTTP 403 to automated requests and the current post-redesign URL could not be confirmed without search.","Statute pages: code.wvlegislature.gov returns HTTP 403 to automated requests (Justia also 403), so statute entries are fetched=false; URLs come from the legislature''s own redirects or Legal Aid WV links.","official_guide: no state-agency or court-published tenant/landlord handbook located; WV Attorney General consumer protection pages contain no landlord-tenant publication.","complaint_filing: WV AG consumer complaint page (https://ago.wv.gov/consumer-protection/file-complaint-consumer-protection-division) does not list landlord-tenant matters, so it was not included.","No separate WV statute sections for rent-increase notice, late fees, landlord entry, or retaliation were identified (retaliation is raised as a defense per Legal Aid WV); could not verify on the official code site.","rent_regulation: preemption status of local rent control could not be confirmed from an official source.","code_enforcement: WV Office of Environmental Health Services sites (oehs.wvdhhr.org) refused connections; no state housing-code page verified.","rental_assistance: no current statewide emergency rental assistance program found (WVHDF homepage does not mention one)."],"rentRegulationCorrections":[]}'::jsonb),
  ('30a13e49-5600-51fe-b9d9-a4f40adab9fd', 'WI', 'Wisconsin', 'state', 'Wis. Stat. ch. 704 (Landlord and Tenant); Wis. Admin. Code ch. ATCP 134 (Residential Rental Practices); Wis. Stat. 799.40-799.45 (small claims eviction actions)', false, 'yes', 'Wisconsin has no statewide rent cap. Wis. Stat. 66.1015(1) bars cities, villages, towns and counties from regulating the amount of rent on private residential rental property.', 'https://docs.legis.wisconsin.gov/document/statutes/66.1015(1)', '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":["Web search was unavailable for this entire session (session search budget exhausted); all URLs were verified by opening them or via links on official/legal-aid pages.","hud_state_page: hud.gov returns HTTP 403 to automated requests and the current post-redesign URL could not be confirmed without search.","Statute pages: docs.legis.wisconsin.gov refused connections all session, so statute entries are fetched=false; URLs were taken from links on the Wisconsin State Law Library and WisLawHelp pages.","court_self_help: wicourts.gov returns HTTP 403 to automated requests; entry is fetched=false.","No separate deep link to Wis. Stat. 704.28 (deposit withholding) at section level was confirmed; ATCP 134.06 is listed instead.","DHS mold page (https://www.dhs.wisconsin.gov/air/mold.htm) returned 404; no state mold page verified.","No local rent-control boards exist (state preemption)."],"rentRegulationCorrections":[]}'::jsonb),
  ('a78b6144-c71a-587e-bda5-5035c6ae3220', 'WY', 'Wyoming', 'state', 'Wyo. Stat. 1-21-1201 to 1-21-1211 (Residential Rental Property); Wyo. Stat. 1-21-1001 to 1-21-1017 (Forcible Entry and Detainer)', false, 'unknown', 'Wyoming has no statewide rent cap, and its Residential Rental Property Act has no rent-amount or rent-increase provision. No local rent control ordinance is known, and no express state preemption appears in the statutes.', 'https://wyoleg.gov/statutes/compress/title01.pdf', '{}'::text[], '2026-10-19T00:00:00Z', '{"gaps":["Web search was unavailable for this entire session (session search budget exhausted); all URLs were verified by opening them or via links on official/legal-aid pages.","hud_state_page: hud.gov returns HTTP 403 to automated requests and the current post-redesign URL could not be confirmed without search.","Statute deep links: wyoleg.gov publishes statutes only as whole-title PDFs, so section entries share the Title 1 PDF URL; Justia fallback returned 403.","No Wyoming statute on rent-increase notice, late fees, landlord entry notice, or retaliation was found in the Residential Rental Property Act (read in full this session).","official_guide: no state-agency or court-published landlord-tenant handbook located.","fair_housing: no Wyoming state fair-housing agency page located; HUD (the likely complaint venue) blocks automated access.","complaint_filing: the Wyoming AG Consumer Protection Unit''s complaint page (https://ag.wyo.gov/law-office-division/consumer-protection-and-antitrust-unit/consumer-complaints) states it will not examine landlord/tenant matters.","court_self_help: Wyoming court sites return a bot challenge; entry is fetched=false and eviction-form availability is unconfirmed.","rental_assistance: no current statewide renter assistance program found (DFS lists none; Wyoming Community Development Authority site returned 403).","health_safety: no Wyoming Department of Health lead, mold or housing page found from the agency homepage; federal EPA pages are listed instead.","rent_regulation: no official source states preemption status either way.","State fair-housing enforcement agency: none exists. The Wyoming Fair Housing Act (W.S. 40-26) needs a HUD-accepted ''enforcing authority'', but the USCCR''s June 2025 brief says the Governor has not assigned one, so complaints go only to HUD Region VIII (Denver). The federal and county resources above fill the fair_housing category.","Opened (fetched) official_guide: none. The Wyoming Judicial Branch Landlord-Tenant PDF is listed but unopened because wyocourts.gov blocks automated access with an AWS WAF challenge. No other state-published guide was found. The WY AG''s Consumer Complaints page lists ''Landlord/Tenant related matters'' among matters it will not examine, and its consumer-education page has no housing material. The Wyoming State Bar ''For the Public'' page, Legal Aid of Wyoming (lawyoming.org) and WYLawHelp have no landlord-tenant guide. wyomingcda.com returned 403.","Process note: the session''s web-search budget ran out after the first queries. Everything after that was found by opening and navigating official sites directly, not by search."],"rentRegulationCorrections":[{"correction":"Minor wording fix: the summary says the official statute PDFs are ''current through 2025 laws'', but title01.pdf now has Last-Modified 2026-05-08, so it likely includes the 2026 session. The substance holds. A re-check found no rent-control, rent-amount or rent-stabilization provision in Titles 1, 15, 18 (counties, which the summary did not mention) or 34, and Article 12 has no rent-increase provision. ''statewideRentCap: false'' and ''localRentControlPreempted: unknown'' are reasonable.","sourceUrl":"https://wyoleg.gov/statutes/compress/title01.pdf"}]}'::jsonb)
